BOOK_DATA = [{'page_no': 1, 'title': "Captain Walton's Letters from the Arctic Ice", 'tr_title': "Kaptan Walton'ın Kutuptan Mektupları ve Buzdaki Dev", 'vocab_focus': [('expedition', 'keşif seferi'), ('continent', 'kıta'), ('iceberg', 'buzdağı'), ('fog', 'yoğun sis'), ('gigantic', 'devasa, dev gibi'), ('sledge', 'kızak'), ('spectacle', 'olağandışı manzara'), ('solitude', 'yalnızlık, ıssızlık')], 'sentences': [{'id': 1, 'text': 'Captain Robert Walton was leading an ambitious expedition to explore the uncharted frozen waters of the North Pole.', 'translation': "Kaptan Robert Walton, Kuzey Kutbu'nun haritalandırılmamış donmuş sularını keşfetmek üzere iddialı bir sefere liderlik ediyordu.", 'notes': 'uncharted frozen waters: haritalandırılmamış donmuş sular.'}, {'id': 2, 'text': 'For months his sturdy sailing ship had battled against freezing winds and monstrous floating mountains of ice.', 'translation': 'Sağlam yelkenli gemisi aylardır dondurucu rüzgarlarla ve devasa yüzen buz dağlarıyla mücadele etmişti.', 'notes': 'floating mountains: yüzen dağlar (buzdağları).'}, {'id': 3, 'text': 'In his letters to his sister Margaret in England, he described the desolate beauty and chilling silence of the Arctic.', 'translation': "İngiltere'deki kız kardeşi Margaret'a yazdığı mektuplarda, Kutup'un o ıssız güzelliğini ve dondurucu sessizliğini tarif ediyordu.", 'notes': 'desolate beauty: ıssız güzellik.'}, {'id': 4, 'text': 'Suddenly, in late July, the ship became completely surrounded by impassable fields of thick pack ice.', 'translation': 'Temmuz sonlarında aniden gemi, geçit vermez kalın buz tarlaları tarafından tamamen kuşatıldı.', 'notes': 'pack ice: deniz buzu örtüsü.'}, {'id': 5, 'text': 'A dense fog settled upon the sea, trapping the crew in terrifying isolation miles from human civilization.', 'translation': 'Denizin üzerine çöken yoğun bir sis, mürettebatı insan medeniyetinden miller boyu uzakta korkunç bir yalnızlığa hapsetti.', 'notes': 'settled upon: üzerine çöktü.'}, {'id': 6, 'text': "About two o'clock the mist cleared away, revealing vast plains of ice stretching endlessly in every direction.", 'translation': 'Saat iki sularında sis dağıldı; her yöne sonsuzca uzanan engin buz düzlüklerini gözler önüne serdi.', 'notes': 'mist cleared away: sis dağıldı.'}, {'id': 7, 'text': 'A strange and astonishing spectacle suddenly attracted the keen attention of the watchful sailors.', 'translation': 'Garip ve şaşırtıcı bir manzara, nöbetteki denizcilerin pürdikkat ilgisini aniden üzerine çekti.', 'notes': 'astonishing spectacle: şaşırtıcı manzara.'}, {'id': 8, 'text': 'At the distance of half a mile, they saw a sledge guided by a gigantic creature having the shape of a man.', 'translation': 'Yarım mil uzakta, bir insan biçimine sahip devasa bir yaratık tarafından yönlendirilen bir kızak gördüler.', 'notes': 'shape of a man: insan biçimi.'}, {'id': 9, 'text': 'The being was of gigantic stature, yet he urged the powerful dogs over the rough ice with astonishing speed.', 'translation': 'Yaratık devasa bir heybete sahipti, yine de güçlü köpekleri engebeli buz üzerinde şaşırtıcı bir hızla sürüyordu.', 'notes': 'gigantic stature: devasa boy pos.'}, {'id': 10, 'text': 'Through their telescopes, they watched the colossal figure until he disappeared among the distant ice hummocks.', 'translation': 'Teleskoplarıyla o devasa silueti uzaktaki buz tümseklerinin arasında kaybolana dek izlediler.', 'notes': 'ice hummocks: buz tümsekleri/tepecikleri.'}, {'id': 11, 'text': 'The sight excited unqualified wonder among the mariners, who believed they were hundreds of miles from any living soul.', 'translation': 'Bu manzara, yaşayan hiçbir candan yüzlerce mil uzakta olduklarına inanan denizciler arasında tarifsiz bir hayret uyandırdı.', 'notes': 'unqualified wonder: tarifsiz hayret.'}, {'id': 12, 'text': 'How could a man, even of such monstrous size, survive alone in that terrible desert of snow?', 'translation': 'Bir insan, böylesine canavarca bir cüsseye sahip olsa bile, o korkunç kar çölünde tek başına nasıl hayatta kalabilirdi?', 'notes': 'how could: nasıl başarabilirdi?'}, {'id': 13, 'text': 'The next morning, as daylight broke over the frozen waste, they found another sledge stranded beside the vessel.', 'translation': 'Ertesi sabah donmuş arazide gün ağarırken, geminin hemen yanında mahsur kalmış bir başka kızak buldular.', 'notes': 'stranded: karaya oturmuş / mahsur kalmış.'}, {'id': 14, 'text': 'Only one dog remained alive out of a whole team, and inside the carriage lay a human being.', 'translation': 'Koca bir köpek takımından geriye sadece tek bir köpek canlı kalmıştı ve kızağın içinde bir insan yatıyordu.', 'notes': 'remained alive: canlı kalmıştı.'}, {'id': 15, 'text': 'He was not a wild giant like the first, but a European gentleman, frozen and on the brink of death.', 'translation': 'İlk yaratık gibi vahşi bir dev değildi bu; donmuş ve ölümün eşiğinde Avrupalı bir beyefendiydi.', 'notes': 'on the brink of death: ölümün eşiğinde.'}, {'id': 16, 'text': 'His limbs were nearly frozen stiff, his eyes held a look of wild madness, and his body was emaciated by starvation.', 'translation': 'Uzuvları neredeyse kaskatı donmuştu, gözlerinde vahşi bir delilik bakışı vardı ve bedeni açlıktan bir deri bir kemik kalmıştı.', 'notes': 'frozen stiff: kaskatı donmuş.'}, {'id': 17, 'text': 'When the sailors offered to bring him aboard, he asked a most unexpected and singular question.', 'translation': 'Denizciler onu güverteye almayı teklif ettiklerinde, son derece beklenmedik ve garip bir soru sordu.', 'notes': 'singular question: tuhaf soru.'}, {'id': 18, 'text': '"Before I come on board your vessel, will you have the kindness to inform me whither you are bound?"', 'translation': '"Geminize adım atmadan önce, lütfedip nereye doğru gitmekte olduğunuzu bana bildirir misiniz?"', 'notes': 'whither you are bound: nereye yöneldiğiniz.'}, {'id': 19, 'text': 'Walton replied that they were on a voyage of discovery toward the North Pole, seeking knowledge.', 'translation': "Walton, bilgi arayışıyla Kuzey Kutbu'na doğru bir keşif yolculuğunda olduklarını yanıtladı.", 'notes': 'seeking knowledge: bilgi arayarak.'}, {'id': 20, 'text': 'Upon hearing this, the stranger sighed deeply, closed his weary eyes, and consented to be hoisted onto the deck.', 'translation': 'Bunu duyunca yabancı derin bir iç çekti, yorgun gözlerini kapattı ve güverteye çekilmeye razı oldu.', 'notes': 'consented to be hoisted: çekilmeye razı geldi.'}]}, {'page_no': 2, 'title': 'Rescuing the Stranger from the Ice', 'tr_title': "Buzdaki Yabancının Kurtarılışı ve Kaptan'a Uyarısı", 'vocab_focus': [('stranger', 'yabancı'), ('cabin', 'kamarası'), ('revive', 'ayıltmak, kendine getirmek'), ('frenzy', 'çılgınlık hali, cinnet'), ('intellect', 'zeka, akıl'), ('benevolence', 'iyilikseverlik, şefkat'), ('catastrophe', 'büyük felaket'), ('demon', 'ifrit, iblis')], 'sentences': [{'id': 21, 'text': "They carried the dying stranger into Captain Walton's private cabin and rubbed his frozen limbs with brandy.", 'translation': "Ölmek üzere olan yabancıyı Kaptan Walton'ın özel kamarasına taşıdılar ve donmuş uzuvlarını konyakla ovdular.", 'notes': 'rubbed frozen limbs: donmuş uzuvlarını ovdu.'}, {'id': 22, 'text': 'Two days elapsed before he was able to speak or consume warm nourishment.', 'translation': 'Konuşabilmesi veya sıcak bir gıda tüketebilmesi için aradan iki gün geçmesi gerekti.', 'notes': 'two days elapsed: iki gün geçti.'}, {'id': 23, 'text': 'Walton felt an immediate and profound affection for this cultured, tragic guest.', 'translation': 'Walton bu kültürlü, trajik konuğa karşı anında derin ve samimi bir yakınlık hissetti.', 'notes': 'profound affection: derin yakınlık/sevgi.'}, {'id': 24, 'text': 'His eyes generally held an expression of settled gloom and despair, yet at times they flashed with brilliant intellect.', 'translation': 'Gözlerinde genellikle yerleşik bir keder ve umutsuzluk ifadesi vardı, fakat bazen parlak bir zekanın ışıltısıyla parlarlardı.', 'notes': 'settled gloom: yerleşik kasvet.'}, {'id': 25, 'text': 'He was gentle, dignified, and possessed of manners so noble that everyone on the ship treated him with reverence.', 'translation': 'Nazikti, vakurdu ve öylesine asil tavırlara sahipti ki gemideki herkes ona büyük bir hürmetle davranıyordu.', 'notes': 'treated with reverence: hürmetle muamele etti.'}, {'id': 26, 'text': 'One day, Walton spoke passionately of his own burning ambition to conquer nature and attain glorious fame.', 'translation': 'Bir gün Walton, doğayı fethetmeye ve şanlı bir şöhrete ulaşmaya dair içindeki o yakıcı hırstan hararetle bahsetti.', 'notes': 'burning ambition: yakıcı hırs.'}, {'id': 27, 'text': '"I would sacrifice my fortune, my existence, my every hope to the furtherance of my enterprise!" Walton declared.', 'translation': '"Girişimimin ilerlemesi uğruna servetimi, varlığımı ve her umudumu feda ederdim!" diye haykırdı Walton.', 'notes': 'furtherance of enterprise: girişimin ilerlemesi.'}, {'id': 28, 'text': 'The stranger groaned in sudden agony, covering his pale face with both emaciated hands.', 'translation': 'Yabancı ani bir ızdırapla inledi; solgun yüzünü bir deri bir kemik kalmış iki eliyle kapattı.', 'notes': 'groaned in agony: ızdırapla inledi.'}, {'id': 29, 'text': '"Unhappy man! Do you share my madness? Have you drunk also of the intoxicating cup of fatal ambition?"', 'translation': '"Talihsiz adam! Sen de mi benim çılgınlığımı paylaşıyorsun? Sen de mi o ölümcül hırsın sarhoş edici kadehinden içtin?"', 'notes': 'intoxicating cup: sarhoş edici kadeh.'}, {'id': 30, 'text': '"Hear me; let me tell you my mournful story, and you will pluck the poison from your heart!"', 'translation': '"Beni dinle; sana hüzünlü hikayemi anlatayım ki kalbindeki o zehri söküp atabilesin!"', 'notes': 'pluck the poison: zehri koparıp almak.'}, {'id': 31, 'text': 'Walton listened with bated breath as the stranger began to unfold his extraordinary history.', 'translation': 'Yabancı o olağanüstü geçmişini gözler önüne sermeye başlarken Walton nefesini tutarak dinledi.', 'notes': 'with bated breath: nefesini tutarak.'}, {'id': 32, 'text': '"I am by birth a Genevese, and my family is one of the most distinguished of that republic,"', 'translation': '"Ben doğma büyüme Cenevreliyim ve ailem o cumhuriyetin en seçkin ailelerinden biridir,"', 'notes': 'distinguished: seçkin, saygın.'}, {'id': 33, 'text': '"My name is Victor Frankenstein, and I was born to wealth, honour, and love."', 'translation': '"Benim adım Victor Frankenstein; varlık, onur ve sevgi dolu bir yuvada dünyaya geldim."', 'notes': 'born to wealth: varlık içine doğmuş.'}, {'id': 34, 'text': '"For many years my life was a paradise of domestic bliss and scientific inquiry."', 'translation': '"Uzun yıllar boyunca hayatım, ailevi saadet ve bilimsel araştırmalarla dolu bir cennetti."', 'notes': 'domestic bliss: aile saadeti.'}, {'id': 35, 'text': '"Yet an insatiable thirst for forbidden knowledge transformed my destiny into a living hell."', 'translation': '"Fakat yasak bilgiye duyduğum doyumsuz susuzluk, kaderimi yaşayan bir cehenneme çevirdi."', 'notes': 'forbidden knowledge: yasak bilgi.'}, {'id': 36, 'text': '"I created a monster, endowed it with life, and unleashed a demon upon those I loved most."', 'translation': '"Bir canavar yarattım, ona hayat bahşettim ve en çok sevdiklerimin üzerine bir iblis saldım."', 'notes': 'endowed with life: hayatla donatılmış.'}, {'id': 37, 'text': '"The being you saw galloping across the ice on that sledge is that very creature, my mortal enemy!"', 'translation': '"O kızakla buzların üzerinde dörtnala gittiğini gördüğünüz varlık tam da o yaratıktır, benim can düşmanım!"', 'notes': 'mortal enemy: can düşmanı.'}, {'id': 38, 'text': '"I have pursued him across continents, through deserts and oceans of ice, to destroy him or perish."', 'translation': '"Onu yok etmek ya da bu uğurda ölmek için kıtalar boyu, çöller ve buz okyanusları boyunca kovaladım."', 'notes': 'to destroy or perish: yok etmek ya da can vermek.'}, {'id': 39, 'text': '"Listen to my tale, Captain Walton, and learn how dangerous is the acquisition of superhuman power."', 'translation': '"Hikayemi dinle Kaptan Walton; insanüstü güçler elde etmenin ne kadar tehlikeli olduğunu öğren."', 'notes': 'acquisition: edinme, kazanma.'}, {'id': 40, 'text': 'And sitting beside the warm stove in the icy cabin, Frankenstein began the chronicle of his tragic life.', 'translation': 'Ve buz gibi kamaradaki sıcak sobanın yanında oturan Frankenstein, trajik hayatının kaydını anlatmaya koyuldu.', 'notes': 'chronicle: tarihçe, kronik.'}]}, {'page_no': 3, 'title': "Victor's Youth in Geneva and Elizabeth", 'tr_title': "Cenevre'deki Mutlu Çocukluk ve Elizabeth Lavenza", 'vocab_focus': [('affection', 'sevgi, şefkat'), ('orphan', 'yetim, öksüz'), ('adopt', 'evlat edinmek'), ('cherish', 'el üstünde tutmak, sevgiyle bağrına basmak'), ('philosophy', 'felsefe, doğa felsefesi'), ('lightning', 'şimşek, yıldırım'), ('companion', 'arkadaş, yoldaş'), ('bliss', 'huzur, büyük saadet')], 'sentences': [{'id': 41, 'text': '"My father was respected by all who knew him for his upright character and tireless public service,"', 'translation': '"Babam, dürüst karakteri ve yorulmak bilmez kamu hizmetleri nedeniyle onu tanıyan herkes tarafından çok sayılırdı,"', 'notes': 'upright character: dürüst/dik duruşlu karakter.'}, {'id': 42, 'text': '"He married Caroline Beaufort, the noble daughter of an impoverished friend, and their union was harmonious."', 'translation': '"Yoksul düşmüş bir dostunun asil kızı Caroline Beaufort ile evlendi ve evlilikleri son derece ahenkliydi."', 'notes': 'impoverished: yoksul düşmüş.'}, {'id': 43, 'text': '"I was their eldest child, idolized and surrounded by tender care from the moment of my birth."', 'translation': '"Onların ilk çocuğuydum; doğduğum andan itibaren el üstünde tutuldum ve şefkatli bir özenle kuşatıldım."', 'notes': 'idolized: el üstünde tutulan.'}, {'id': 44, 'text': '"When I was five years old, my parents made an excursion to the lovely shores of Lake Como in Italy."', 'translation': '"Ben beş yaşındayken ailem, İtalya\'daki Como Gölü\'nün o harika sahillerine bir seyahat yaptı."', 'notes': 'excursion: gezi, seyahat.'}, {'id': 45, 'text': '"In a poor peasant cottage, my mother discovered an angelic orphan child named Elizabeth Lavenza."', 'translation': '"Yoksul bir köylü kulübesinde annem, Elizabeth Lavenza adında melek yüzlü bir yetim kız çocuğu keşfetti."', 'notes': 'angelic orphan: melek gibi yetim.'}, {'id': 46, 'text': '"Her mother was a German lady who died in giving her birth, and her father was an Italian nobleman."', 'translation': '"Annesi onu doğururken ölen bir Alman hanımdı; babası ise İtalyan bir soyluydu."', 'notes': 'nobleman: soylu adam.'}, {'id': 47, 'text': '"She had golden hair, eyes dark and clear like mountain lakes, and an angelic disposition."', 'translation': '"Altın sarısı saçları, dağ gölleri gibi berrak ve koyu renk gözleri ve melek gibi bir huyu vardı."', 'notes': 'angelic disposition: melek gibi tabiat/huy.'}, {'id': 48, 'text': '"My mother adopted her, and from that day Elizabeth became my cherished sister, companion, and idol."', 'translation': '"Annem onu evlat edindi ve o günden sonra Elizabeth benim el üstünde tuttuğum kardeşim, yoldaşım ve kutup yıldızım oldu."', 'notes': 'cherished: el üstünde tutulan.'}, {'id': 49, 'text': '"Everyone loved Elizabeth; she brought gentle harmony, beauty, and music into our happy home."', 'translation': '"Herkes Elizabeth\'i severdi; mutlu yuvamıza tatlı bir ahenk, güzellik ve musiki getirdi."', 'notes': 'gentle harmony: tatlı ahenk.'}, {'id': 50, 'text': '"My dearest schoolfellow was Henry Clerval, the son of a Geneva merchant, full of romantic chivalry."', 'translation': '"En sevgili okul arkadaşım ise romantik şövalyelik duygularıyla dolu, Cenevreli bir tüccarın oğlu Henry Clerval\'dı."', 'notes': 'romantic chivalry: romantik şövalyelik.'}, {'id': 51, 'text': '"While Clerval loved heroic tales and languages, my passion was directed toward the secrets of nature."', 'translation': '"Clerval kahramanlık destanlarına ve dillere tutkuluyken, benim merakım tabiatın sırlarına yönelmişti."', 'notes': 'secrets of nature: tabiatın sırları.'}, {'id': 52, 'text': '"I was eager to learn the hidden laws of the physical universe, heaven and earth alike."', 'translation': '"Fiziki evrenin, hem göğün hem yerin gizli yasalarını öğrenmeye can atıyordum."', 'notes': 'heaven and earth alike: hem gök hem yer.'}, {'id': 53, 'text': '"At the age of thirteen, I accidentally found the works of ancient alchemists like Cornelius Agrippa and Paracelsus."', 'translation': '"On üç yaşındayken tesadüfen Cornelius Agrippa ve Paracelsus gibi eski simyacıların eserlerini buldum."', 'notes': 'ancient alchemists: eski simyacılar.'}, {'id': 54, 'text': '"I poured over their fantastic pages, dreaming of discovering the philosopher\'s stone and the elixir of eternal life."', 'translation': '"Felsefe taşını ve ölümsüzlük iksirini keşfetmeyi hayal ederek onların fantastik sayfalarına gömüldüm."', 'notes': 'elixir of life: ölümsüzlük iksiri.'}, {'id': 55, 'text': '"When I was fifteen, we witnessed a most violent and terrible thunderstorm in the mountains."', 'translation': '"On beş yaşımdayken dağlarda son derece şiddetli ve korkunç bir gök gürültülü fırtınaya tanık olduk."', 'notes': 'violent thunderstorm: şiddetli fırtına.'}, {'id': 56, 'text': '"As I looked on, a dazzling bolt of lightning struck a magnificent oak tree standing near our house."', 'translation': '"Ben izlerken, evimizin yakınında duran muhteşem bir meşe ağacına göz kamaştırıcı bir yıldırım çarptı."', 'notes': 'bolt of lightning: yıldırım oku/çakması.'}, {'id': 57, 'text': '"In an instant, the ancient tree was reduced to charred splinters of smoking wood."', 'translation': '"Bir anda o asırlık ağaç, tüten tahtalardan kömürleşmiş kıymıklara dönüştü."', 'notes': 'charred splinters: kömürleşmiş kıymıklar.'}, {'id': 58, 'text': '"I was astonished by the supreme and terrifying power of electricity and modern natural science."', 'translation': '"Elektriğin ve modern doğa biliminin o yüce ve korkunç gücü karşısında hayrete düştüm."', 'notes': 'astonished by: karşısında hayrete düşmüş.'}, {'id': 59, 'text': '"It seemed to me that natural philosophy was the true key to unlocking the deepest mysteries of creation."', 'translation': '"Bana öyle geliyordu ki doğa felsefesi, yaratılışın en derin sırlarını açacak hakiki anahtardı."', 'notes': 'deepest mysteries: en derin gizemler.'}, {'id': 60, 'text': '"Fatal curiosity! It was the first step on the road to my eternal destruction."', 'translation': '"Ölümcül merak! Benim ebedi mahvıma giden yoldaki ilk adımdı bu."', 'notes': 'fatal curiosity: ölümcül merak.'}]}, {'page_no': 4, 'title': 'Studies at Ingolstadt and the Secret of Life', 'tr_title': 'Ingolstadt Üniversitesi ve Yaşamın Kaynağının Keşfi', 'vocab_focus': [('university', 'üniversite'), ('chemistry', 'kimya'), ('anatomy', 'anatomi'), ('decay', 'çürüme, bozulma'), ('charnel-house', 'kemiklik, ceset mahzeni'), ('vitality', 'yaşam gücü, canlılık'), ('spark', 'kıvılcım'), ('creation', 'yaratılış, yaratma')], 'sentences': [{'id': 61, 'text': '"When I was seventeen years old, my parents resolved that I should become a student at the University of Ingolstadt in Germany."', 'translation': '"On yedi yaşıma geldiğimde ailem, Almanya\'daki Ingolstadt Üniversitesi\'nde öğrenim görmeme karar verdi."', 'notes': 'resolved that: karar kıldı.'}, {'id': 62, 'text': '"Just before my departure, a terrible tragedy struck: my beloved mother caught scarlet fever from nursing Elizabeth and died."', 'translation': '"Ayrılışımdan hemen önce korkunç bir trajedi yaşandı: sevgili annem Elizabeth\'e bakarken kızıl hastalığına yakalandı ve vefat etti."', 'notes': 'scarlet fever: kızıl hastalığı.'}, {'id': 63, 'text': '"On her deathbed, she joined our hands and begged Elizabeth and me to become united in marriage in future years."', 'translation': '"Ölüm döşeğindeyken ellerimizi birleştirdi ve ileriki yıllarda Elizabeth ile evlilik bağıyla birleşmemiz için bana yalvardı."', 'notes': 'deathbed: ölüm döşeği.'}, {'id': 64, 'text': '"With a heavy heart torn by grief, I travelled alone to Ingolstadt to begin my academic pursuits."', 'translation': '"Kederle paramparça olmuş ağır bir yürekle, akademik çalışmalarıma başlamak üzere yapayalnız Ingolstadt\'a gittim."', 'notes': 'torn by grief: kederle parçalanmış.'}, {'id': 65, 'text': '"There I met Professor Waldman, a brilliant chemist whose inspiring lecture completely altered my destiny."', 'translation': '"Orada, ilham verici dersi kaderimi tamamen değiştiren dahi kimyager Profesör Waldman ile tanıştım."', 'notes': 'inspiring lecture: ilham verici ders.'}, {'id': 66, 'text': '"He told us that modern scientists had acquired almost godlike powers over the elements of nature."', 'translation': '"Bize, modern bilim insanlarının doğanın elementleri üzerinde neredeyse tanrısal güçler kazandığını anlattı."', 'notes': 'godlike powers: tanrısal güçler.'}, {'id': 67, 'text': '"I threw myself into the study of chemistry and human anatomy with feverish, unremitting zeal."', 'translation': '"Hummalı ve dinmek bilmez bir şevkle kendimi kimya ve insan anatomisi çalışmalarına verdim."', 'notes': 'unremitting zeal: dinmeyen şevk.'}, {'id': 68, 'text': '"In two years I made discoveries that astonished the professors and students of the whole university."', 'translation': '"İki yıl içinde bütün üniversitenin profesörlerini ve öğrencilerini hayrete düşüren keşifler yaptım."', 'notes': 'astonished: hayrete düşürdü.'}, {'id': 69, 'text': '"I asked myself: Whence does the principle of life proceed? What is the secret of existence?"', 'translation': '"Kendi kendime sordum: Yaşam ilkesi nereden kaynaklanır? Varlığın sırrı nedir?"', 'notes': 'whence: nereden (eski İngilizce).'}, {'id': 70, 'text': '"To examine the causes of life, we must first have recourse to death and biological decomposition."', 'translation': '"Yaşamın nedenlerini incelemek için, önce ölüme ve biyolojik çürümeye başvurmak zorundayız."', 'notes': 'have recourse to: ...e başvurmak.'}, {'id': 71, 'text': '"I spent solitary nights in vaults and charnel-houses, observing the natural decay and corruption of human flesh."', 'translation': '"İnsan etinin doğal çürümesini ve bozulmasını gözlemleyerek mahzenlerde ve ceset mezarlıklarında yapayalnız geceler geçirdim."', 'notes': 'corruption of flesh: etin çürümesi.'}, {'id': 72, 'text': '"I saw how the fine form of man was degraded and wasted by worms and mold."', 'translation': '"İnsanın o zarif biçiminin kurtlar ve küfler tarafından nasıl alçaltılıp yok edildiğini gördüm."', 'notes': 'degraded and wasted: alçaltılmış ve ziyan edilmiş.'}, {'id': 73, 'text': '"Suddenly, amidst this darkness, a sudden light broke in upon me—a brilliant, dazzling revelation!"', 'translation': '"Birdenbire, bu karanlığın ortasında üzerime ani bir ışık doğdu—parlak, göz kamaştırıcı bir vahiy gibi!"', 'notes': 'dazzling revelation: göz kamaştırıcı aydınlanma.'}, {'id': 74, 'text': '"I alone possessed the secret of bestowing animation upon lifeless matter!"', 'translation': '"Cansız maddeye canlılık ve hareket bahşetmenin sırrına sadece ve sadece ben sahiptim!"', 'notes': 'bestowing animation: canlılık bahşetmek.'}, {'id': 75, 'text': '"No one before me had ever uncovered this supreme mystery since the creation of the world."', 'translation': '"Dünyanın yaratılışından bu yana benden önce hiç kimse bu yüce gizemi gün yüzüne çıkaramamıştı."', 'notes': 'supreme mystery: yüce gizem.'}, {'id': 76, 'text': '"I resolved to create a human being, to build a colossal frame endowed with vital breath."', 'translation': '"Bir insan varlığı yaratmaya, yaşamsal nefesle donatılmış devasa bir beden inşa etmeye karar verdim."', 'notes': 'colossal frame: devasa gövde/beden.'}, {'id': 77, 'text': '"Because the minute parts slowed down my work, I determined to make the creature eight feet in height."', 'translation': '"Küçük uzuv parçaları işimi yavaşlattığı için, yaratığı sekiz fit boyunda yapmaya karar verdim."', 'notes': 'eight feet in height: sekiz fit boyunda.'}, {'id': 78, 'text': '"A new species would bless me as its creator and source; many happy natures would owe their being to me."', 'translation': '"Yeni bir tür beni yaratıcısı ve kaynağı olarak kutsayacaktı; nice mutlu varlıklar var oluşlarını bana borçlu olacaktı."', 'notes': 'owe their being: varlıklarını borçlu olmak.'}, {'id': 79, 'text': '"For nearly a year, in my lonely garret laboratory, I collected bones and tissues from dissecting rooms."', 'translation': '"Neredeyse bir yıl boyunca, yalnız tavan arası laboratuvarımda kadavra odalarından kemikler ve dokular topladım."', 'notes': 'dissecting rooms: kadavra/otopsi odaları.'}, {'id': 80, 'text': '"My cheeks grew pale with study, and my eyes became hollow as I approached the fatal climax."', 'translation': '"Çalışmaktan yanaklarım soldu ve o meşum zirveye yaklaşırken gözlerim çukurlarına çöktü."', 'notes': 'fatal climax: ölümcül doruk noktası.'}]}, {'page_no': 5, 'title': 'The Dreadful Night of Creation', 'tr_title': 'Kasım Ayında Korkunç Yaratılış Gecesi: Canavar Uyanıyor', 'vocab_focus': [('dreary', 'kasvetli, hüzünlü'), ('spark', 'kıvılcım'), ('candle', 'mum'), ('convulsion', 'kasılma, sarsılma'), ('artery', 'atardamar'), ('horrid', 'korkunç, iğrenç'), ('catastrophe', 'felaket, yıkım'), ('breathless', 'soluksuz, nefessiz')], 'sentences': [{'id': 81, 'text': '"It was on a dreary night of November that I beheld the accomplishment of my long toils."', 'translation': '"Uzun uğraşlarımın tamamlandığını gördüğüm an, kasvetli bir kasım gecesiydi."', 'notes': 'dreary night: kasvetli gece.'}, {'id': 82, 'text': '"With an anxiety that almost amounted to agony, I collected the instruments of life around me."', 'translation': '"Neredeyse ızdıraba varan bir kaygıyla, yaşam araç gereçlerini etrafıma topladım."', 'notes': 'amounted to agony: ızdıraba vardı.'}, {'id': 83, 'text': '"I prepared to infuse a spark of being into the lifeless thing that lay at my feet upon the table."', 'translation': '"Masanın üzerinde ayaklarımın dibinde yatan o cansız şeye bir var oluş kıvılcımı aşılamaya hazırlandım."', 'notes': 'infuse a spark: bir kıvılcım aşılamak.'}, {'id': 84, 'text': '"It was already one in the morning; the rain pattered dismally against the window-panes."', 'translation': '"Saat çoktan gecenin biri olmuştu; yağmur kasvetle pencere camlarına çarpıyordu."', 'notes': 'pattered dismally: kasvetle pıtır pıtır vurdu.'}, {'id': 85, 'text': '"My candle was nearly burnt out, flickering feebly in its pool of melted tallow."', 'translation': '"Mumum neredeyse tükenmişti; erimiş içyağı birikintisinin içinde cılızca titreşiyordu."', 'notes': 'flickering feebly: cılızca titreşerek.'}, {'id': 86, 'text': '"By the glimmer of the half-extinguished light, I saw the dull yellow eye of the creature open."', 'translation': '"Yarı sönmüş o ışığın soluk pırıltısında, yaratığın donuk sarı gözünün açıldığını gördüm."', 'notes': 'dull yellow eye: donuk sarı göz.'}, {'id': 87, 'text': '"It breathed hard, and a convulsive motion agitated its giant limbs."', 'translation': '"Derin derin nefes aldı ve sarsıntılı bir kasılma devasa uzuvlarını titretti."', 'notes': 'convulsive motion: kasılmalı hareket.'}, {'id': 88, 'text': '"How can I describe my emotions at this catastrophe, or how delineate the wretch whom with such infinite pains I had formed?"', 'translation': '"Bu felaket karşısındaki duygularımı nasıl tarif edebilirim ya da böylesine sonsuz zahmetlerle vücuda getirdiğim o sefili nasıl tasvir edebilirim?"', 'notes': 'how delineate: nasıl betimlemeli.'}, {'id': 89, 'text': '"His limbs were in proportion, and I had selected his features as beautiful."', 'translation': '"Uzuvları orantılıydı ve yüz hatlarını güzel olsun diye bizzat seçmiştim."', 'notes': 'in proportion: orantılı.'}, {'id': 90, 'text': '"Beautiful! Great God! His yellow skin scarcely covered the work of muscles and arteries beneath."', 'translation': '"Güzel mi! Yüce Tanrım! Sarı derisi altındaki kasların ve atardamarların dokusunu ancak örtüyordu."', 'notes': 'scarcely covered: güçbela örtüyordu.'}, {'id': 91, 'text': '"His hair was of a lustrous black, and flowing; his teeth of a pearly whiteness."', 'translation': '"Saçları dalgalı ve parlak simsiyahtı; dişleri inci gibi bembeyazdı."', 'notes': 'pearly whiteness: inci gibi beyazlık.'}, {'id': 92, 'text': '"But these luxuriances only formed a more horrid contrast with his watery eyes, that seemed almost of the same colour as the dun-white sockets in which they were set."', 'translation': '"Fakat bu zenginlikler, içine yerleştikleri kül rengi beyaz yuvalarla neredeyse aynı renkte görünen sulu gözleriyle yalnızca daha korkunç bir tezat oluşturuyordu."', 'notes': 'horrid contrast: korkunç tezat.'}, {'id': 93, 'text': '"His shrivelled complexion and straight black lips filled me with unspeakable disgust."', 'translation': '"Kırışmış ten rengi ve dümdüz siyah dudakları beni kelimelere dökülemez bir tiksintiyle doldurdu."', 'notes': 'unspeakable disgust: anlatılamaz tiksinti.'}, {'id': 94, 'text': '"The beauty of the dream vanished, and breathless horror and disgust filled my trembling heart."', 'translation': '"Rüyanın güzelliği yok olup gitti; titreyen yüreğimi soluksuz bir dehşet ve tiksinti kapladı."', 'notes': 'beauty vanished: güzellik yok oldu.'}, {'id': 95, 'text': '"Unable to endure the aspect of the being I had created, I rushed out of the room."', 'translation': '"Yarattığım varlığın o çehresine tahammül edemeyerek odadan dışarı fırladım."', 'notes': 'unable to endure: dayanamayarak.'}, {'id': 96, 'text': '"I threw myself on the bed in my dressing-room, seeking in vain to find refuge in sleep."', 'translation': '"Uykuda nafile bir sığınak bulma umuduyla giyinme odamdaki yatağa kendimi attım."', 'notes': 'seeking in vain: nafile yere arayarak.'}, {'id': 97, 'text': '"Horrible nightmares haunted my slumbers: I embraced Elizabeth, but she turned into the corpse of my dead mother!"', 'translation': '"Uykumu korkunç kabuslar bastı: Elizabeth\'e sarılıyordum ama o kollarımda ölmüş annemin cesedine dönüşüyordu!"', 'notes': 'turned into corpse: cesede dönüştü.'}, {'id': 98, 'text': '"I started from my sleep with horror; cold dews covered my forehead, and my teeth chattered."', 'translation': '"Dehşet içinde uykumdan fırladım; alnımı soğuk terler kaplamıştı ve dişlerim birbirine çarpıyordu."', 'notes': 'teeth chattered: dişleri takırdadı.'}, {'id': 99, 'text': '"By the dim yellow light of the moon, I beheld the wretch—the miserable monster whom I had created."', 'translation': '"Ayın loş sarı ışığında o sefili—kendi yarattığım o bedbaht canavarı gördüm."', 'notes': 'beheld the wretch: o sefili gördüm.'}, {'id': 100, 'text': '"He held up the curtain of the bed, his jaws opened, and he muttered some inarticulate sounds while a grin wrinkled his cheeks."', 'translation': '"Yatağın perdesini araladı, çenesi açıldı; yanağını buruşturan bir sırıtışla anlaşılmaz sesler mırıldanarak elini bana doğru uzattı."', 'notes': 'inarticulate sounds: anlaşılmaz sesler.'}]}, {'page_no': 6, 'title': 'Flight from the Monster and Henry Clerval', 'tr_title': 'Canavardan Kaçış, Henry Clerval ile Karşılaşma ve Ateşli Hastalık', 'vocab_focus': [('refuge', 'sığınak'), ('coach', 'posta arabası'), ('delirium', 'sayıklama, hezeyan'), ('fever', 'ateş, humma'), ('devotion', 'bağlılık, fedakar dostluk'), ('convalescence', 'nekahat, iyileşme dönemi'), ('collapse', 'yığılmak, çökmek'), ('spectre', 'hayalet, hortlak')], 'sentences': [{'id': 101, 'text': '"He stretched out one hand, seemingly to detain me, but I escaped and rushed downstairs in terror."', 'translation': '"Beni alıkoymak istercesine bir elini uzattı, fakat ben kurtuldum ve dehşet içinde merdivenlerden aşağı koştum."', 'notes': 'seemingly to detain: alıkoymak istercesine.'}, {'id': 102, 'text': '"I took refuge in the courtyard belonging to the house which I inhabited, where I remained during the rest of the night."', 'translation': '"Oturduğum evin avlusuna sığındım ve gecenin geri kalanını orada geçirdim."', 'notes': 'took refuge: sığındı.'}, {'id': 103, 'text': '"I paced up and down in the drizzling rain, listening in agony to every sound of the dark street."', 'translation': '"Karanlık sokağın her sesini ızdırapla dinleyerek çiseleyen yağmurun altında bir aşağı bir yukarı voltaladım."', 'notes': 'paced up and down: volta attı.'}, {'id': 104, 'text': '"Morning at last arrived, grey and dismal, and I wandered like a madman through the streets of Ingolstadt."', 'translation': '"Nihayet kurşuni ve kasvetli bir sabah geldi ve ben Ingolstadt sokaklarında bir deli gibi dolaştım."', 'notes': 'wandered like a madman: deli gibi dolaştı.'}, {'id': 105, 'text': '"I dared not return to the apartment where that demon of my own creation was lurking."', 'translation': '"Kendi yarattığım o iblisin pusuya yattığı o daireye geri dönmeye cesaret edemiyordum."', 'notes': 'dared not: cesaret edemedi.'}, {'id': 106, 'text': '"At length I arrived opposite the inn at which the Swiss diligence and stagecoaches stopped."', 'translation': '"Nihayet İsviçre posta arabalarının durduğu hanın karşısına vardım."', 'notes': 'diligence: büyük yolcu arabası.'}, {'id': 107, 'text': '"A coach had just arrived; the door opened, and who should step out but my dearest friend, Henry Clerval!"', 'translation': '"Bir araba henüz varmıştı; kapı açıldı ve inen kişi en sevgili dostum Henry Clerval\'dan başkası değildi!"', 'notes': 'who should step out but: inen başkası değildi.'}, {'id': 108, 'text': '"My dear Frankenstein!" he cried, embracing me warmly. "How extraordinarily fortunate that you are here to meet me!"', 'translation': '"Sevgili Frankenstein\'ım!" diye haykırdı bana sımsıkı sarılarak. "Beni karşılamak üzere burada olman ne fevkalade bir talih!"', 'notes': 'extraordinarily fortunate: olağanüstü şanslı.'}, {'id': 109, 'text': '"His presence brought back all the sweet memories of Geneva, of Elizabeth, and of my happy youth."', 'translation': '"Onun mevcudiyeti Cenevre\'nin, Elizabeth\'in ve mutlu gençliğimin bütün tatlı hatıralarını geri getirdi."', 'notes': 'sweet memories: tatlı anılar.'}, {'id': 110, 'text': '"Yet Clerval was immediately alarmed by my emaciated appearance and wild, unhinged eyes."', 'translation': '"Yine de Clerval bir deri bir kemik kalmış halimden ve vahşi, yuvalarından fırlamış gözlerimden ötürü derhal telaşlandı."', 'notes': 'unhinged eyes: yuvalarından fırlamış gözler.'}, {'id': 111, 'text': '"My dear Victor," said he, "what, for God\'s sake, is the matter? Are you ill? You look like a ghost!"', 'translation': '"Sevgili Victor," dedi, "Tanrı aşkına neyin var? Hasta mısın? Hortlak gibi görünüyorsun!"', 'notes': 'what is the matter: neyin var?'}, {'id': 112, 'text': '"I assured him that I was well, only fatigued by unremitting study, and led him to my lodgings."', 'translation': '"İyi olduğuma, yalnızca aralıksız çalışmaktan yorulduğuma dair onu temin ettim ve kaldığım eve götürdüm."', 'notes': 'fatigued: yorgun düşmüş.'}, {'id': 113, 'text': '"As we climbed the stairs, I trembled violently, dreading to behold the monster in my chamber."', 'translation': '"Merdivenleri çıkarken, odamda o canavarla karşılaşmaktan ölesiye korkarak şiddetle titriyordum."', 'notes': 'dreading to behold: görmekten dehşetle korkarak.'}, {'id': 114, 'text': '"I threw the door open hastily and stepped in first: the apartment was completely empty!"', 'translation': '"Kapıyı aceleyle ardına kadar açtım ve ilk önce ben içeri adım attım: daire tamamen boştu!"', 'notes': 'threw door open: kapıyı açıp fırlattı.'}, {'id': 115, 'text': '"The creature had vanished! I clapped my hands in joyful ecstasy, laughing hysterically."', 'translation': '"Yaratık yok olmuştu! Histerik kahkahalar atarak sevinç dolu bir vecdle ellerimi birbirine çırptım."', 'notes': 'joyful ecstasy: sevinç dolu kendinden geçiş.'}, {'id': 116, 'text': '"Clerval was astonished by my strange behaviour, believing that I had completely lost my reason."', 'translation': '"Aklımı tamamen yitirdiğime inanan Clerval bu garip davranışlarım karşısında donakaldı."', 'notes': 'lost my reason: aklımı yitirdim.'}, {'id': 117, 'text': '"Suddenly, the strain proved too great; I collapsed upon the floor in a violent nervous fever."', 'translation': '"Birdenbire bu gerilim çok ağır geldi; şiddetli bir sinir humması nöbetiyle yere yığıldım."', 'notes': 'strain proved too great: gerilim çok ağır geldi.'}, {'id': 118, 'text': '"For several months I lay raving in delirium, hovering between life and death."', 'translation': '"Aylarca hezeyanlar içinde sayıklayarak hayat ile ölüm arasında gidip geldim."', 'notes': 'hovering between: arasında gidip gelerek.'}, {'id': 119, 'text': '"Henry Clerval was my constant nurse, watching over me with sisterly tenderness and devotion."', 'translation': '"Henry Clerval bana kardeşçe bir şefkat ve vefayla göz kulak olarak daimi hemşirem oldu."', 'notes': 'sisterly tenderness: kardeşçe şefkat.'}, {'id': 120, 'text': '"He concealed the severity of my illness from my father and Elizabeth, sparing them mortal agony."', 'translation': '"Hastalığımın vehametini babamdan ve Elizabeth\'ten sakladı; onları kahredici bir ızdıraptan esirgedi."', 'notes': 'sparing them: onları esirgeyerek.'}]}, {'page_no': 7, 'title': 'The Murder of Little William', 'tr_title': "Küçük William'ın Cinayeti ve Cenevre'den Gelen Kara Mektup", 'vocab_focus': [('tragedy', 'trajedi'), ('strangle', 'boğarak öldürmek'), ('sorrow', 'keder, elem'), ('innocence', 'masumiyet'), ('miniature', 'küçük portre, madalyon'), ('locket', 'madalyon'), ('grief', 'büyük acı'), ('mourn', 'yas tutmak')], 'sentences': [{'id': 121, 'text': '"By the arrival of spring, my health was completely restored thanks to Clerval\'s devoted nursing."', 'translation': '"Baharın gelişiyle birlikte, Clerval\'ın o özverili bakımı sayesinde sağlığıma tamamen kavuştum."', 'notes': 'restored: toparlandı, iyileşti.'}, {'id': 122, 'text': '"I introduced Henry to the university professors, but the sight of chemical apparatus made me shudder."', 'translation': '"Henry\'yi üniversite profesörleriyle tanıştırdım, fakat kimya aletlerini görmek bile beni titretiyordu."', 'notes': 'made me shudder: beni ürpertti/titretti.'}, {'id': 123, 'text': '"We planned to return together to Geneva, where Elizabeth and my family were eagerly expecting us."', 'translation': '"Elizabeth\'in ve ailemin bizi sabırsızlıkla beklediği Cenevre\'ye birlikte dönmeyi planladık."', 'notes': 'eagerly expecting: hevesle bekleyen.'}, {'id': 124, 'text': '"On the eve of our planned journey, a letter arrived from my father bearing terrible news."', 'translation': '"Planladığımız yolculuğun arifesinde babamdan korkunç haberler taşıyan bir mektup geldi."', 'notes': 'bearing terrible news: korkunç haberler taşıyan.'}, {'id': 125, 'text': '"My trembling hands broke the black wax seal, and my eyes scanned the heartbroken lines."', 'translation': '"Titreyen ellerim siyah mühür mumunu kırdı ve gözlerim o kahredici satırları taradı."', 'notes': 'black wax seal: siyah mühür mumu.'}, {'id': 126, 'text': '"My dearest Victor," wrote my father, "how can I relate to you our utter misery and despair?"', 'translation': '"En sevgili Victor\'ım," diye yazmıştı babam, "uğradığımız o mutlak sefaleti ve umutsuzluğu sana nasıl aktarabilirim?"', 'notes': 'utter misery: mutlak sefalet/kahır.'}, {'id': 127, 'text': '"William, your darling little brother, is dead!"', 'translation': '"William, senin o canın ciğerin küçük kardeşin, öldü!"', 'notes': 'is dead: öldü.'}, {'id': 128, 'text': '"That sweet child, whose smiles and innocence delighted us all, has been brutally murdered!"', 'translation': '"Gülüşleri ve masumiyeti hepimizi sevindiren o tatlı çocuk, vahşice katledildi!"', 'notes': 'brutally murdered: vahşice katledilmiş.'}, {'id': 129, 'text': '"Last Thursday evening, we took our customary walk in the meadows of Plainpalais."', 'translation': '"Geçtiğimiz perşembe akşamı Plainpalais çayırlarında her zamanki yürüyüşümüze çıktık."', 'notes': 'customary walk: mutat yürüyüş.'}, {'id': 130, 'text': '"William and his younger brother Ernest ran ahead of us to play among the trees."', 'translation': '"William ve küçük kardeşi Ernest ağaçların arasında oynamak için bizim önümüzden koştular."', 'notes': 'ran ahead: önden koştular.'}, {'id': 131, 'text': '"When night fell, William did not return; we searched frantically with torches until dawn."', 'translation': '"Gece çöktüğünde William dönmedi; şafak sökene kadar meşalelerle deliler gibi aradık."', 'notes': 'searched frantically: delicesine aradık.'}, {'id': 132, 'text': '"At five in the morning, I found the lovely child lying upon the grass, cold and motionless."', 'translation': '"Sabah saat beşte o sevimli çocuğu otların üzerinde kaskatı ve hareketsiz yatarken buldum."', 'notes': 'cold and motionless: soğuk ve hareketsiz.'}, {'id': 133, 'text': '"The print of murderous fingers was deeply bruised upon his pale throat; he had been strangled!"', 'translation': '"Katil parmakların izi solgun gırtlağında morarmış halde duruyordu; boğularak öldürülmüştü!"', 'notes': 'print of murderous fingers: katil parmakların izi.'}, {'id': 134, 'text': '"Elizabeth is utterly inconsolable; she accuses herself of having caused his death."', 'translation': '"Elizabeth tamamen teselli bulamaz halde; onun ölümüne sebep olduğu gerekçesiyle kendini suçluyor."', 'notes': 'inconsolable: teselli edilemez.'}, {'id': 135, 'text': '"She had given William a valuable miniature portrait of his mother to wear around his neck,"', 'translation': '"Boynuna takması için William\'a annesinin kıymetli bir minyatür portresini vermişti,"', 'notes': 'miniature portrait: minyatür portre.'}, {'id': 136, 'text': '"And the precious locket has been stolen by the assassin, suggesting robbery as the motive."', 'translation': '"Ve o değerli madalyon katil tarafından çalınmış; bu da cinayetin soygun amacıyla işlendiğini düşündürüyor."', 'notes': 'precious locket: kıymetli madalyon.'}, {'id': 137, 'text': '"Come, dearest Victor; not brooding in revenge, but bringing peace and healing to our broken hearts."', 'translation': '"Gel en sevgili Victor\'ım; intikam hırsıyla değil, kırık kalplerimize huzur ve şifa getirerek gel."', 'notes': 'brooding in revenge: intikamla yanıp tutuşarak.'}, {'id': 138, 'text': '"Clerval saw the letter drop from my paralyzed fingers and read the dreadful words himself."', 'translation': '"Clerval mektubun felç olmuş parmaklarımdan düştüğünü gördü ve o korkunç sözleri bizzat okudu."', 'notes': 'paralyzed fingers: donakalmış parmaklar.'}, {'id': 139, 'text': '"I ordered post-horses immediately and set out alone for Geneva, weeping tears of agony."', 'translation': '"Derhal menzil atları sipariş ettim ve ızdırap gözyaşları dökerek tek başıma Cenevre\'ye doğru yola koyuldum."', 'notes': 'post-horses: menzil/posta atları.'}, {'id': 140, 'text': '"William, my innocent, beautiful little brother, murdered by a ruthless hand! But whose hand?"', 'translation': '"William, o masum, güzel küçük kardeşim acımasız bir el tarafından katledilmişti! Fakat kimin eliydi bu?"', 'notes': 'ruthless hand: acımasız el.'}]}, {'page_no': 8, 'title': 'The Shadow on Mont Salêve', 'tr_title': 'Mont Salêve Kayalıklarındaki Devasa Gölge: Katil Yaratıktır!', 'vocab_focus': [('glacier', 'buzul'), ('thunderstorm', 'gök gürültülü fırtına'), ('lightning', 'şimşek'), ('colossal', 'muazzam, devasa'), ('daemon', 'ifrit, şeytan'), ('guilt', 'suçluluk, vicdan azabı'), ('unmask', 'maskesini düşürmek'), ('precipice', 'uçurum, sarp kayalık')], 'sentences': [{'id': 141, 'text': '"My journey was melancholy beyond words as I approached the beloved mountains of my homeland."', 'translation': '"Memleketimin o sevgili dağlarına yaklaşırken yolculuğum kelimelerin ötesinde hüzün doluydu."', 'notes': 'beyond words: kelimelerin ötesinde.'}, {'id': 142, 'text': '"I beheld the lake; the white dome of Mont Blanc towered majestically into the purple evening sky."', 'translation': '"Gölü gördüm; Mont Blanc\'ın beyaz kubbesi mor akşam göğüne doğru haşmetle yükseliyordu."', 'notes': 'white dome: beyaz kubbe.'}, {'id': 143, 'text': '"By the time I reached the outskirts of Geneva, night had fallen, and the city gates were locked."', 'translation': '"Cenevre surlarına vardığımda gece çökmüştü ve şehrin kapıları kilitlenmişti."', 'notes': 'outskirts: dış mahalleler, surlar.'}, {'id': 144, 'text': '"I resolved to spend the night in the village of Secheron and visit the scene of William\'s murder at Plainpalais."', 'translation': '"Geceyi Secheron köyünde geçirmeye ve William\'ın katledildiği Plainpalais\'deki olay yerini ziyaret etmeye karar verdim."', 'notes': 'resolved to spend: geçirmeye karar verdi.'}, {'id': 145, 'text': '"A sudden and magnificent thunderstorm broke over the lake, echoing like rolling artillery among the Alps."', 'translation': '"Gölün üzerinde, Alpler arasında gürleyen toplar gibi yankılanan ani ve görkemli bir fırtına patlak verdi."', 'notes': 'rolling artillery: gürleyen topçu ateşi.'}, {'id': 146, 'text': '"Dazzling sheets of lightning illuminated the dark waters and the jagged crests of the mountains."', 'translation': '"Göz kamaştırıcı şimşek tabakaları kara suları ve dağların sivri doruklarını aydınlatıyordu."', 'notes': 'jagged crests: sivri doruklar.'}, {'id': 147, 'text': '"As I walked toward the spot where my brother\'s body had been found, another brilliant flash lit up the gloom."', 'translation': '"Kardeşimin cesedinin bulunduğu noktaya doğru yürürken, bir başka parlak şimşek karanlığı aydınlattı."', 'notes': 'lit up the gloom: karanlığı aydınlattı.'}, {'id': 148, 'text': '"A colossal figure stepped out from a clump of trees, illuminated in sharp relief by the lightning."', 'translation': '"Şimşeğin keskin ışığıyla apaçık aydınlanan bir ağaç kümesinin arkasından devasa bir siluet öne çıktı."', 'notes': 'sharp relief: keskin hatlarla.'}, {'id': 149, 'text': '"A flash of lightning illuminated the object, and discovered its shape plainly to me; its gigantic stature, and the deformity of its aspect more hideous than belongs to humanity, instantly informed me that it was the wretch, the filthy daemon, to whom I had given life."', 'translation': '"Bir şimşek çakması nesneyi aydınlattı ve biçimini bana apaçık gösterdi; devasa boyu ve insanlığa ait olamayacak kadar iğrenç biçim bozukluğu, bana derhal onun kendi hayat verdiğim o sefil, o pis iblis olduğunu bildirdi."', 'notes': 'filthy daemon: pis ifrit.'}, {'id': 150, 'text': '"Could he be the murderer of my brother? No sooner did that idea enter my imagination than I was convinced."', 'translation': '"Kardeşimin katili o olabilir miydi? Bu fikir aklıma girer girmez kesin olarak ikna oldum."', 'notes': 'no sooner than: girer girmez.'}, {'id': 151, 'text': '"The teeth chattered in my head; my breath stopped; I felt as if an icy hand gripped my heart."', 'translation': '"Dişlerim kafamın içinde birbirine vurdu; nefesim kesildi; sanki buz gibi bir el yüreğimi kavramıştı."', 'notes': 'teeth chattered: dişleri birbirine çarptı.'}, {'id': 152, 'text': '"The monster bounded over the rocks with supernatural agility, scaling the steep precipice of Mont Salêve."', 'translation': '"Canavar doğaüstü bir çeviklikle kayaların üzerinden sıçradı; Mont Salêve\'in dimdik uçurumuna tırmandı."', 'notes': 'scaling precipice: uçuruma tırmanarak.'}, {'id': 153, 'text': '"In a few moments he reached the summit and vanished among the storm clouds."', 'translation': '"Birkaç dakika içinde zirveye ulaştı ve fırtına bulutlarının arasında gözden kayboldu."', 'notes': 'reached summit: zirveye ulaştı.'}, {'id': 154, 'text': '"He was the murderer! I had unleashed an indestructible fiend upon the earth to murder my own flesh and blood!"', 'translation': '"Katil oydu! Kendi canımı ve kanımı katletsin diye yeryüzüne yok edilemez bir ifrit salmıştım!"', 'notes': 'indestructible fiend: yok edilemez iblis.'}, {'id': 155, 'text': '"I remained motionless through the storm, soaked by the rain, weeping bitter tears of unutterable guilt."', 'translation': '"Yağmurla sırılsıklam olmuş halde, anlatılmaz suçluluğun acı gözyaşlarını dökerek fırtınanın ortasında öylece hareketsiz kaldım."', 'notes': 'unutterable guilt: tarif edilemez suçluluk.'}, {'id': 156, 'text': '"Two years had elapsed since I had given him life; was this only the beginning of his bloody vengeance?"', 'translation': '"Ona hayat vermemin üzerinden iki yıl geçmişti; bu onun kanlı intikamının yalnızca başlangıcı mıydı yoksa?"', 'notes': 'two years had elapsed: iki yıl geçmişti.'}, {'id': 157, 'text': '"I thought of declaring the truth to the judges, but who would believe my fantastic tale?"', 'translation': '"Yargıçlara gerçeği açıklamayı düşündüm, fakat benim bu fantastik hikayeme kim inanırdı ki?"', 'notes': 'declaring truth: gerçeği açıklamak.'}, {'id': 158, 'text': '"They would consider me a raving madman and dismiss my accusation as the delirium of a sick brain."', 'translation': '"Beni zırdeli bir kaçık sayarlar ve suçlamamı hasta bir beynin sayıklaması diyerek bir kenara atarlardı."', 'notes': 'raving madman: zırdeli adam.'}, {'id': 159, 'text': '"I resolved to keep my dreadful secret buried deep within my tormented breast."', 'translation': '"O korkunç sırrımı ızdırap çeken göğsümün derinliklerine gömmeye karar verdim."', 'notes': 'tormented breast: acı çeken göğüs.'}, {'id': 160, 'text': '"When the city gates opened at dawn, I hurried home, where a new and shocking horror awaited me."', 'translation': '"Şafakta şehir kapıları açıldığında hızla eve koştum; orada beni yeni ve şok edici bir dehşet bekliyordu."', 'notes': 'hurried home: eve koşturdu.'}]}, {'page_no': 9, 'title': 'The Trial and Tragedy of Justine Moritz', 'tr_title': "Masum Justine Moritz'in Yargılanması ve İdamı", 'vocab_focus': [('innocence', 'masumiyet'), ('servant', 'hizmetkar'), ('accuse', 'suçlamak, itham etmek'), ('evidence', 'kanıt, delil'), ('guilty', 'suçlu'), ('confession', 'itiraf'), ('scaffold', 'darağacı, idam sehpası'), ('remorse', 'vicdan azabı, derin pişmanlık')], 'sentences': [{'id': 161, 'text': '"When I reached my father\'s house, Ernest met me at the door with tears of bitter anguish."', 'translation': '"Babamın evine vardığımda, Ernest acı bir kederin gözyaşlarıyla beni kapıda karşıladı."', 'notes': 'bitter anguish: acı keder/ıstırap.'}, {'id': 162, 'text': '"He told me that the murderer had been discovered and arrested by the magistrates!"', 'translation': '"Bana katilin yargıçlar tarafından tespit edilip tutuklandığını söyledi!"', 'notes': 'had been discovered: bulunmuştu.'}, {'id': 163, 'text': '"Good God! Who is it?" I cried, knowing that the real monster was wandering free upon the mountains.', 'translation': '"Yüce Tanrım! Kim peki?" diye haykırdım, gerçek canavarın dağlarda serbestçe dolaştığını bilerek.', 'notes': 'wandering free: serbestçe dolaşarak.'}, {'id': 164, 'text': '"It is Justine Moritz, our gentle, devoted servant girl whom our mother loved like a daughter!"', 'translation': '"Annemizin bir evlat gibi sevdiği o nazik, vefalı hizmetkar kızımız Justine Moritz!"', 'notes': 'devoted servant: vefalı hizmetçi.'}, {'id': 165, 'text': '"Justine? Impossible! She loved William with maternal tenderness!" I exclaimed in horror.', 'translation': '"Justine mi? İmkansız! O William\'ı anne şefkatiyle severdi!" diye haykırdım dehşet içinde.', 'notes': 'maternal tenderness: anne şefkati.'}, {'id': 166, 'text': '"The evidence was damning: the gold miniature locket of my mother had been discovered in her pocket."', 'translation': '"Kanıt kahrediciydi: annemin altın minyatür madalyonu onun cebinde bulunmuştu."', 'notes': 'evidence was damning: delil ezici/kahrediciydi.'}, {'id': 167, 'text': '"I knew instantly that the monster had placed it there to frame the innocent girl!"', 'translation': '"Masum kıza tuzak kurmak için onu oraya o canavarın koyduğunu anında anladım!"', 'notes': 'to frame: tuzak kurmak / üstüne atmak.'}, {'id': 168, 'text': '"The trial took place the next day, and Elizabeth and I sat in the courtroom with bleeding hearts."', 'translation': '"Dava ertesi gün görüldü ve Elizabeth ile ben mahkeme salonunda kan ağlayan yüreklerle oturduk."', 'notes': 'trial took place: duruşma yapıldı.'}, {'id': 169, 'text': '"Justine appeared calm, sustained by the consciousness of her absolute innocence."', 'translation': '"Justine mutlak masumiyetinin bilinciyle güç bularak sakin görünüyordu."', 'notes': 'consciousness of innocence: masumiyet bilinci.'}, {'id': 170, 'text': '"She explained that she had spent the night searching for the lost boy, but could not explain the locket."', 'translation': '"Geceyi kayıp çocuğu arayarak geçirdiğini açıkladı, fakat madalyonu izah edemedi."', 'notes': 'could not explain: açıklayamadı.'}, {'id': 171, 'text': '"Elizabeth gave a passionate speech defending her noble character, moving many in the crowd to tears."', 'translation': '"Elizabeth onun asil karakterini savunan hararetli bir konuşma yaptı ve kalabalıktan birçok kişiyi gözyaşlarına boğdu."', 'notes': 'passionate speech: ateşli konuşma.'}, {'id': 172, 'text': '"Yet circumstantial evidence prevailed; the judges returned a verdict of guilty, and she was condemned to death."', 'translation': '"Yine de dolaylı deliller galip geldi; yargıçlar suçlu kararı verdiler ve kız idama mahkum edildi."', 'notes': 'circumstantial evidence: dolaylı delil.'}, {'id': 173, 'text': '"A priest threatened her with excommunication and hellfire until, in terror and confusion, she confessed a falsehood."', 'translation': '"Bir rahip onu aforoz edilmekle ve cehennem ateşiyle tehdit etti; ta ki dehşet ve şaşkınlık içinde o yalanı itiraf edene dek."', 'notes': 'confessed a falsehood: yalan itiraf etti.'}, {'id': 174, 'text': '"I visited her in the dark prison cell before her execution, where she forgave her persecutors with saintly grace."', 'translation': '"İdamından önce onu karanlık zindan hücresinde ziyaret ettim; orada kendisine zulmedenleri azizce bir zarafetle bağışladı."', 'notes': 'saintly grace: azizce zarafet.'}, {'id': 175, 'text': '"The next morning, innocent Justine died upon the scaffold, murdered by human law as William had been by the monster."', 'translation': '"Ertesi sabah masum Justine darağacında can verdi; tıpkı William\'ın canavar tarafından katledildiği gibi o da insan kanunu tarafından katledilmişti."', 'notes': 'died upon the scaffold: darağacında öldü.'}, {'id': 176, 'text': '"Anguish and despair penetrated into the core of my heart; I bore a hell within me which nothing could extinguish."', 'translation': '"Acı ve umutsuzluk yüreğimin en derin merkezine işledi; içimde hiçbir şeyin söndüremeyeceği bir cehennem taşıyordum."', 'notes': 'bore a hell: bir cehennem taşıdı.'}, {'id': 177, 'text': '"William and Justine were only the first unhappy victims of my unhallowed arts!"', 'translation': '"William ve Justine, benim o lanetli sanatlarımın yalnızca ilk talihsiz kurbanlarıydı!"', 'notes': 'unhallowed arts: lanetli/kutsal olmayan sanatlar.'}, {'id': 178, 'text': '"My father\'s health broke under the double blow of sorrow, and Elizabeth\'s joyous spirit was extinguished."', 'translation': '"Babamın sağlığı bu çifte keder darbesi altında çöktü ve Elizabeth\'in o neşe dolu ruhu tamamen söndü."', 'notes': 'joyous spirit was extinguished: neşeli ruh söndü.'}, {'id': 179, 'text': '"I wandered like an evil spirit, fleeing the society of men, contemplating suicide in the dark waters of the lake."', 'translation': '"İnsanların arasından kaçarak, gölün kara sularında intiharı tasarlayarak kötücül bir hayalet gibi dolaştım."', 'notes': 'contemplating suicide: intiharı düşünerek.'}, {'id': 180, 'text': '"Only my love for Elizabeth and my burning desire for vengeance prevented me from ending my miserable life."', 'translation': '"Yalnızca Elizabeth\'e duyduğum aşk ve içimdeki yakıcı intikam arzusu sefil hayatıma son vermemi engelledi."', 'notes': 'burning desire for vengeance: yakıcı intikam arzusu.'}]}, {'page_no': 10, 'title': 'Encounter on the Sea of Ice', 'tr_title': "Buz Denizi'nde Korkunç Yüzleşme ve Yaratığın Talebi", 'vocab_focus': [('glacier', 'buzul, buz nehri'), ('pinnacle', 'sivri dağ zirvesi'), ('avalanche', 'çığ'), ('confront', 'yüzleşmek, karşı karşıya gelmek'), ('supplicate', 'yalvarmak, istirham etmek'), ('creator', 'yaratıcı'), ('duty', 'görev, mesuliyet'), ('misery', 'sefalet, büyük acı')], 'sentences': [{'id': 181, 'text': '"Seeking relief from my intolerable anguish, I undertook a solitary journey to the valley of Chamounix."', 'translation': '"Dayanılmaz ızdırabımdan bir nebze kurtuluş arayarak, Chamounix vadisine yapayalnız bir yolculuğa çıktım."', 'notes': 'intolerable anguish: dayanılmaz ızdırap.'}, {'id': 182, 'text': '"The sublime and magnificent scenes of the Alps elevated my soul from the degrading sorrow of mortality."', 'translation': '"Alplerin o yüce ve görkemli manzaraları, ruhumu faniliğin o alçaltıcı kederinden çekip yukarı kaldırdı."', 'notes': 'sublime scenes: yüce manzaralar.'}, {'id': 183, 'text': '"The tumbling avalanches and icy torrents spoke to me of an omnipotent power far greater than human grief."', 'translation': '"Yuvarlanan çığlar ve buzlu akıntılar bana insan kederinden çok daha üstün, her şeye kadir bir güçten bahsetti."', 'notes': 'omnipotent power: her şeye gücü yeten kudret.'}, {'id': 184, 'text': '"One morning I climbed alone to the summit of Montanvert, overlooking the vast Mer de Glace."', 'translation': '"Bir sabah o engin Buz Denizi\'ne tepeden bakan Montanvert\'in zirvesine tek başıma tırmandım."', 'notes': 'Mer de Glace: Buz Denizi (Fransızca).'}, {'id': 185, 'text': '"The Sea of Ice was a winding ocean of frozen waves, surrounded by colossal granite needles piercing the clouds."', 'translation': '"Buz Denizi, bulutları delen devasa granit iğnelerle çevrili, donmuş dalgalardan oluşan kıvrımlı bir okyanustu."', 'notes': 'granite needles: granit iğneler/zirveler.'}, {'id': 186, 'text': '"As I stood contemplating the solemn beauty, I saw the figure of a man advancing toward me over the ice."', 'translation': '"Bu vakur güzelliği seyrederek dururken, buzun üzerinden bana doğru yaklaşan bir adam silueti gördüm."', 'notes': 'advancing toward: doğru yaklaşan.'}, {'id': 187, 'text': '"He bounded over the crevasses with superhuman speed and agility, his stature exceeding that of ordinary men."', 'translation': '"Buzul yarıklarının üzerinden insanüstü bir hız ve çeviklikle atladı; cüssesi sıradan insanlarınkini fersah fersah aşıyordu."', 'notes': 'exceeding stature: cüssesi aşan.'}, {'id': 188, 'text': '"As he drew nearer, a trembling sensation seized my limbs; it was the wretch whom I had created!"', 'translation': '"Daha da yaklaştığında uzuvlarımı tir tir bir titreme sardı; bu, kendi ellerimle yarattığım o sefildi!"', 'notes': 'trembling sensation: titreme hissi.'}, {'id': 189, 'text': '"Rage and hatred choked my voice as he approached, towering over me with bitter dignity."', 'translation': '"Acı bir vakarla tepemde dikilerek yaklaştığında öfke ve nefret sesimi boğazıma tıkadı."', 'notes': 'bitter dignity: acı vakar.'}, {'id': 190, 'text': '"Devil!" I exclaimed. "Do you dare approach me? Do you not fear the fierce vengeance of my arm?"', 'translation': '"İblis!" diye haykırdım. "Bana yaklaşmaya cüret mi ediyorsun? Kolumun o amansız intikamından korkmuyor musun?"', 'notes': 'fierce vengeance: amansız intikam.'}, {'id': 191, 'text': '"Begone, vile insect! Or stay, that I may trample you to dust!"', 'translation': '"Defol git aşağılık böcek! Ya da kal da seni ayaklarımın altında toz gibi ezeyim!"', 'notes': 'trample to dust: çiğneyip toz etmek.'}, {'id': 192, 'text': '"I expected this reception," said the daemon, in a deep, sonorous, and melancholy voice.', 'translation': '"Böyle bir karşılamayı bekliyordum zaten," dedi ifrit derin, çınlayan ve kederli bir ses tonuyla.', 'notes': 'sonorous voice: çınlayan/gür ses.'}, {'id': 193, 'text': '"All men hate the wretched; how, then, must I be hated, who am miserable beyond all living things!"', 'translation': '"Tüm insanlar sefillerden nefret eder; öyleyse yaşayan her şeyden daha bedbaht olan benden nasıl nefret edilmesin!"', 'notes': 'miserable beyond: ötesinde bedbaht.'}, {'id': 194, 'text': '"Yet you, my creator, detest and spurn me, your creature, to whom you are bound by ties only dissoluble by the annihilation of one of us."', 'translation': '"Yine de sen, benim yaratıcım; ancak birimizin yok oluşuyla çözülebilecek bağlarla bağlı olduğun yaratığından iğreniyor ve onu kovuyorsun."', 'notes': 'detest and spurn: iğrenmek ve kovmak.'}, {'id': 195, 'text': '"You purpose to kill me. How dare you sport thus with life?"', 'translation': '"Beni öldürmeyi tasarlıyorsun. Hayatla böylesine oynamaya nasıl cüret edersin?"', 'notes': 'sport with life: hayatla oyun oynamak.'}, {'id': 196, 'text': '"Do your duty towards me, and I will do mine towards you and the rest of mankind."', 'translation': '"Bana karşı olan görevini yerine getir; ben de sana ve insanlığın geri kalanına karşı olan görevimi yerine getireyim."', 'notes': 'do your duty: görevini yap.'}, {'id': 197, 'text': '"If you refuse, I will glut the maw of death, until it be satiated with the blood of your remaining friends."', 'translation': '"Eğer reddedersen, ölümün o aç kursağını geriye kalan dostlarının kanıyla tıka basa doyana kadar besleyeceğim."', 'notes': 'glut the maw: kursağını doyurmak.'}, {'id': 198, 'text': '"Abhorred monster! Fie on your threats!" I answered. "There can be no community between you and me; we are enemies!"', 'translation': '"Nefretlik canavar! Lanet olsun tehditlerine!" diye yanıtladım. "Seninle benim aramda hiçbir ortaklık olamaz; biz düşmanız!"', 'notes': 'abhorred: tiksinilen, nefret edilen.'}, {'id': 199, 'text': '"Hear my story!" the creature pleaded with passionate eloquence. "I was benevolent and good; misery made me a fiend."', 'translation': '"Hikayemi dinle!" diye yalvardı yaratık coşkulu bir belagatle. "Ben iyi kalpli ve şefkatliydim; beni iblis yapan bu sefalet oldu."', 'notes': 'passionate eloquence: coşkulu belagat.'}, {'id': 200, 'text': '"Make me happy, and I shall again be virtuous; listen to me, Frankenstein, before you pass sentence upon my head!"', 'translation': '"Beni mutlu et, yine erdemli olayım; kafama ölüm fermanını indirmeden önce beni dinle Frankenstein!"', 'notes': 'pass sentence: hüküm vermek.'}]}, {'page_no': 11, 'title': "The Creature's First Senses in the Forest", 'tr_title': 'Yaratığın İlk Duyumları, Ormandaki Yalnızlık ve Ateş', 'vocab_focus': [('sensation', 'duyum, his'), ('radiance', 'parlaklık, ışıltı'), ('nourishment', 'besin, gıda'), ('instinct', 'içgüdü'), ('desolate', 'ıssız, terk edilmiş'), ('embers', 'közler, korlar'), ('coarse', 'kaba, pürüzlü'), ('solitary', 'yapayalnız')], 'sentences': [{'id': 201, 'text': '"Compelled by a strange mixture of curiosity and pity, I followed the creature to his mountain hut."', 'translation': '"Merak ve acımanın tuhaf bir karışımıyla sürüklenerek, dağdaki kulübesine kadar yaratığı takip ettim."', 'notes': 'compelled by: ...nin zoruyla.'}, {'id': 202, 'text': '"There, beside a small fire, the daemon sat down and began the narrative of his existence."', 'translation': '"Orada, küçük bir ateşin başında ifrit oturdu ve var oluşunun hikayesini anlatmaya başladı."', 'notes': 'narrative of existence: var oluş anlatısı.'}, {'id': 203, 'text': '"It is with considerable difficulty that I remember the original era of my being," began the monster.', 'translation': '"Varlığımın o ilk dönemini hatırlamam son derece güçtür," diye başladı canavar.', 'notes': 'original era: başlangıç dönemi.'}, {'id': 204, 'text': '"All the events of that period appear confused and indistinct, a chaotic rush of light and darkness."', 'translation': '"O dönemin bütün olayları karmaşık ve belirsiz görünüyor; ışık ve karanlığın kaotik bir akışı gibi."', 'notes': 'chaotic rush: kaotik akış.'}, {'id': 205, 'text': '"A strange multiplicity of sensations seized me, and I saw, felt, heard, and smelt at the same time."', 'translation': '"Tuhaf bir duyumlar çokluğu beni sardı ve aynı anda hem gördüm, hem hissettim, hem işittim hem de kokladım."', 'notes': 'multiplicity of sensations: hisler çokluğu.'}, {'id': 206, 'text': '"Light pressed upon my nerves, so that I was obliged to shut my eyes in acute pain."', 'translation': '"Işık sinirlerime öylesine baskı yaptı ki, keskin bir acı içinde gözlerimi kapamak zorunda kaldım."', 'notes': 'pressed upon: baskı yaptı.'}, {'id': 207, 'text': '"I was a poor, helpless, miserable wretch; I knew, and could distinguish, nothing."', 'translation': '"Zavallı, çaresiz, bedbaht bir sefildim; hiçbir şey bilmiyor ve hiçbir şeyi ayırt edemiyordum."', 'notes': 'could distinguish nothing: hiçbir şeyi ayırt edemezdim.'}, {'id': 208, 'text': '"Feeling the pain of the light invade me on all sides, I fled from your apartment into the forest of Ingolstadt."', 'translation': '"Işığın acısının beni dört bir yandan kuşattığını hissederek senin dairenden çıkıp Ingolstadt ormanına kaçtım."', 'notes': 'invade: istila etmek, kuşatmak.'}, {'id': 209, 'text': '"I wandered in that forest, weeping like a helpless infant, chilled by the frost and wet with the rain."', 'translation': '"Ayazdan üşümüş ve yağmurla ıslanmış halde, çaresiz bir bebek gibi ağlayarak o ormanda başıboş dolaştım."', 'notes': 'chilled by frost: ayazdan donmuş.'}, {'id': 210, 'text': '"Hunger and thirst tormented me; I ate wild berries from the bushes and drank cold water from a brook."', 'translation': '"Açlık ve susuzluk bana eziyet etti; çalılardan yaban mersini yedim ve bir dereden soğuk sular içtim."', 'notes': 'tormented: eziyet etti.'}, {'id': 211, 'text': '"One night, looking up through the branches, I saw a gentle, radiant light illuminate the sky."', 'translation': '"Bir gece dalların arasından yukarı baktığımda, gökyüzünü aydınlatan tatlı, parlak bir ışık gördüm."', 'notes': 'radiant light: parıldayan ışık.'}, {'id': 212, 'text': '"It was the silver moon, which gave me immense pleasure and guided my steps through the gloom."', 'translation': '"Bana muazzam bir sevinç veren ve karanlıkta adımlarıma rehberlik eden gümüş aydı bu."', 'notes': 'immense pleasure: muazzam sevinç/haz.'}, {'id': 213, 'text': '"I was delighted by the sweet songs of the birds, and sought in vain to imitate their pleasant notes."', 'translation': '"Kuşların tatlı ezgileri karşısında büyülendim ve onların o güzel nağmelerini taklit etmeye nafile çalıştım."', 'notes': 'sought in vain: nafile uğraştı.'}, {'id': 214, 'text': '"One cold day, I found a fire which had been left by some wandering beggars, burning cheerfully."', 'translation': '"Soğuk bir günde, oradan geçen bazı dilenciler tarafından geride bırakılmış, neşeyle yanan bir ateş buldum."', 'notes': 'wandering beggars: gezgin dilenciler.'}, {'id': 215, 'text': '"I thrust my hand into the live embers in childish joy, and cried out in agony at the searing pain!"', 'translation': '"Çocukça bir sevinçle elimi kor halindeki közlerin içine soktum ve yakıcı acıyla feryat ettim!"', 'notes': 'searing pain: yakıcı acı.'}, {'id': 216, 'text': '"How strange, I thought, that the same cause should produce such opposite effects of warmth and suffering!"', 'translation': '"Aynı sebebin böylesine zıt sıcaklık ve acı sonuçları doğurması ne tuhaf, diye düşündüm!"', 'notes': 'opposite effects: zıt etkiler.'}, {'id': 217, 'text': '"I learned that dry wood preserved the flame, and I kept the fire alive with watchful care."', 'translation': '"Kuru odunun alevi beslediğini öğrendim ve pürdikkat bir özenle ateşi canlı tuttum."', 'notes': 'watchful care: dikkatli özen.'}, {'id': 218, 'text': '"I roasted wild roots and acorns upon the coals, finding them far more delicious than raw food."', 'translation': '"Közlerin üzerinde yabani kökleri ve palamutları pişirdim; onları çiğ yiyeceklerden çok daha lezzetli bularak."', 'notes': 'roasted acorns: közlenmiş meşe palamutları.'}, {'id': 219, 'text': '"When winter came, snow covered the earth, freezing the nuts and berries, and food became scarce."', 'translation': '"Kış geldiğinde kar yeryüzünü kapladı; yemişleri ve meyveleri dondurdu; yiyecek kıtlaştı."', 'notes': 'became scarce: kıtlaştı.'}, {'id': 220, 'text': '"Desperate with hunger, I resolved to venture toward human dwellings in search of food and shelter."', 'translation': '"Açlıktan gözüm dönmüş halde, yiyecek ve barınak aramak üzere insan yerleşimlerine gitmeye karar verdim."', 'notes': 'in search of: arayışında.'}]}, {'page_no': 12, 'title': 'The De Lacey Cottage and the Chink in the Wall', 'tr_title': 'De Lacey Kulübesi ve Duvardaki Gizli Çatlak', 'vocab_focus': [('cottage', 'kır evi, kulübe'), ('hovel', 'derme çatma baraka, sundurma'), ('chink', 'delik, tahta çatlağı'), ('crevice', 'çatlak, yarık'), ('blind', 'kör, görme engelli'), ('venerable', 'saygıdeğer, muhterem'), ('gentleness', 'nezaket, yumuşak başlılık'), ('paradise', 'cennet')], 'sentences': [{'id': 221, 'text': '"I entered a shepherd\'s small stone hut one morning to seek bread and warmth."', 'translation': '"Bir sabah ekmek ve sıcaklık aramak üzere bir çobanın küçük taş kulübesine girdim."', 'notes': "shepherd's hut: çoban kulübesi."}, {'id': 222, 'text': '"An old man was sitting by the fire; on seeing me, he shrieked loudly and fled across the fields in terror."', 'translation': '"Yaşlı bir adam ateşin başında oturuyordu; beni görünce avazı çıktığı kadar çığlık attı ve dehşet içinde tarlalara kaçtı."', 'notes': 'shrieked loudly: yüksek sesle çığlık attı.'}, {'id': 223, 'text': '"Later, I entered a large village, where children screamed, women fainted, and men pelted me with stones and clubs."', 'translation': '"Daha sonra büyük bir köye girdim; orada çocuklar çığlık attı, kadınlar bayıldı ve adamlar beni taş ve sopa yağmuruna tuttu."', 'notes': 'pelted with stones: taş yağmuruna tuttu.'}, {'id': 224, 'text': '"Grievously bruised and wounded, I escaped to the open country and found refuge in a low hovel beside a neat cottage."', 'translation': '"Ağır şekilde ezilmiş ve yaralanmış halde açık araziye kaçtım ve düzenli bir kulübenin yanındaki alçak bir sundurmaya sığındım."', 'notes': 'found refuge: sığınak buldu.'}, {'id': 225, 'text': '"The hovel was built of wood, joined to the cottage, filled with dry straw that provided warm bedding."', 'translation': '"Kulübeye bitişik ahşaptan yapılmış bu sundurma, sıcak bir yatak sağlayan kuru samanla doluydu."', 'notes': 'dry straw: kuru saman.'}, {'id': 226, 'text': '"In one wall, through a small chink where a knot of wood had fallen out, I could see directly into the cottage room."', 'translation': '"Duvarın bir yerinde, bir budak düşmüş olan küçük bir çatlaktan doğrudan kulübenin odasının içini görebiliyordum."', 'notes': 'small chink: küçük çatlak/aralık.'}, {'id': 227, 'text': '"The inhabitants consisted of an old, silver-haired man, a gentle young woman, and a sturdy young youth."', 'translation': '"Evin sakinleri gümüş saçlı yaşlı bir adam, nazik genç bir kadın ve sağlam yapılı bir delikanlıdan oluşuyordu."', 'notes': 'silver-haired: ak saçlı.'}, {'id': 228, 'text': '"The old man was blind; he played upon an instrument which produced divine, heartbreaking melodies."', 'translation': '"Yaşlı adam kördü; ilahi, yürek burkan ezgiler çıkaran telli bir enstrüman çalıyordu."', 'notes': 'divine melodies: ilahi nağmeler.'}, {'id': 229, 'text': '"The young woman, Agatha, performed household duties with patient sweetness, while the youth, Felix, toiled in the garden."', 'translation': '"Genç kadın Agatha sabırlı bir tatlılıkla ev işlerini yapıyor, delikanlı Felix ise bahçede kan ter içinde çalışıyordu."', 'notes': 'patient sweetness: sabırlı bir tatlılık.'}, {'id': 230, 'text': '"They loved each other with tenderest devotion, kissing the old man\'s hands and cheering his dark world."', 'translation': '"Yaşlı adamın ellerini öperek ve onun karanlık dünyasını aydınlatarak birbirlerini en derin sevgiyle seviyorlardı."', 'notes': 'tenderest devotion: en şefkatli bağlılık.'}, {'id': 231, 'text': '"I watched them day after day, fascinated by a beauty and gentleness I had never imagined existed."', 'translation': '"Varlığını daha önce hiç hayal edemediğim bir güzellik ve zarafet karşısında büyülenerek onları günbegün izledim."', 'notes': 'fascinated by: ile büyülenmiş.'}, {'id': 232, 'text': '"Yet I observed that a cloud of deep sorrow often hung over their gentle brows."', 'translation': '"Yine de o masum alınlarının üzerinde çoğu zaman derin bir keder bulutunun gezindiğini fark ettim."', 'notes': 'cloud of sorrow: keder bulutu.'}, {'id': 233, 'text': '"At first I could not understand why such virtuous people should be unhappy."', 'translation': '"İlk başta böylesine erdemli insanların neden mutsuz olduğunu bir türlü anlayamadım."', 'notes': 'virtuous people: erdemli insanlar.'}, {'id': 234, 'text': '"At length I discovered the cause: they were suffering from extreme, bitter poverty."', 'translation': '"Sonunda sebebi keşfettim: son derece ağır, amansız bir yoksulluk çekiyorlardı."', 'notes': 'bitter poverty: amansız yoksulluk.'}, {'id': 235, 'text': '"Their food was scanty, often consisting only of roots, coarse dark bread, and a little milk."', 'translation': '"Yiyecekleri pek kıttı; çoğu zaman sadece köklerden, kara kaba ekmekten ve azıcık sütten ibaretti."', 'notes': 'scanty: kıt, yetersiz.'}, {'id': 236, 'text': '"Often the young people placed all the food before their blind father, going entirely without food themselves."', 'translation': '"Gençler çoğu zaman tüm yiyeceği kör babalarının önüne koyuyor, kendileri ise tamamen aç kalıyorlardı."', 'notes': 'going without food: aç kalarak.'}, {'id': 237, 'text': '"This trait of kindness touched me sensible; I had been accustomed to steal part of their store for my hunger."', 'translation': '"Bu iyilik duygusu beni derinden etkiledi; oysa ben açlığım için onların erzağından çalmaya alışmıştım."', 'notes': 'touched me sensible: beni derinden sarstı/etkiledi.'}, {'id': 238, 'text': '"From that day I resolved never to touch their food again, but contented myself with berries and acorns in the woods."', 'translation': '"O günden sonra bir daha asla onların yiyeceğine dokunmamaya karar verdim; ormandaki meyveler ve palamutlarla yetindim."', 'notes': 'contented myself with: ile yetindim.'}, {'id': 239, 'text': '"Moreover, I sought to relieve their distress: during the night, I cut large piles of firewood and left them at their door."', 'translation': '"Dahası, onların sıkıntısını hafifletmeye çalıştım: geceleyin büyük odun yığınları kesip kapılarının önüne bıraktım."', 'notes': 'relieve distress: sıkıntıyı hafifletmek.'}, {'id': 240, 'text': '"When Felix found the wood in the morning, he regarded it as the miraculous gift of a friendly forest spirit."', 'translation': '"Sabah odunları bulduğunda Felix, bunu dostane bir orman perisinin mucizevi bir hediyesi olarak gördü."', 'notes': 'miraculous gift: mucizevi hediye.'}]}, {'page_no': 13, 'title': 'Learning Language and the Soul of Books', 'tr_title': "Dili Öğrenmek, Safie'nin Gelişi ve Üç Büyük Kitap", 'vocab_focus': [('articulate', 'düzgün konuşmak, kelimeleri telaffuz etmek'), ('pronounce', 'telaffuz etmek'), ('sympathy', 'sempati, duygudaşlık'), ('exile', 'sürgün'), ('paradise', 'cennet'), ('eloquence', 'belagat, güzel konuşma'), ('deformity', 'sakatlık, şekil bozukluğu'), ('affection', 'sevgi, şefkat')], 'sentences': [{'id': 241, 'text': '"I spent the whole winter in this secluded manner, observing my beloved protectors through the wall."', 'translation': '"Bütün kışı bu inziva halinde, duvarın ardından sevgili koruyucularımı izleyerek geçirdim."', 'notes': 'secluded manner: münzevi/inziva tarzı.'}, {'id': 242, 'text': '"I discovered that these people possessed a method of communicating their experience and feelings to one another by articulate sounds."', 'translation': '"Bu insanların tecrübelerini ve duygularını birbirlerine anlaşılır seslerle aktarma yöntemine sahip olduklarını keşfettim."', 'notes': 'articulate sounds: telaffuz edilen sesler.'}, {'id': 243, 'text': '"I perceived that the words they spoke sometimes produced pleasure or pain, smiles or sadness, in the minds of the hearers."', 'translation': '"Söyledikleri kelimelerin dinleyenlerin zihinlerinde bazen haz ya da acı, tebessüm ya da hüzün yarattığını fark ettim."', 'notes': 'perceived: idrak ettim / farkına vardım.'}, {'id': 244, 'text': '"This was indeed a godlike science, and I ardently desired to understand and pronounce their language."', 'translation': '"Bu sahiden tanrısal bir ilimdi ve ben onların dilini anlamayı ve telaffuz etmeyi tutkuyla arzuladım."', 'notes': 'godlike science: tanrısal ilim.'}, {'id': 245, 'text': '"By great application I learned the words for \'fire\', \'milk\', \'bread\', \'wood\', \'brother\', and \'sister\'."', 'translation': '"Büyük bir gayretle \'ateş\', \'süt\', \'ekmek\', \'odun\', \'kardeş\' ve \'abla\' kelimelerini öğrendim."', 'notes': 'great application: büyük çaba/gayret.'}, {'id': 246, 'text': '"In spring, a beautiful Turkish lady named Safie arrived at the cottage on horseback, seeking Felix."', 'translation': '"İlkbaharda, Safie adında güzel bir Türk hanımefendi at sırtında kulübeye çıkageldi; Felix\'i arayarak."', 'notes': 'on horseback: at sırtında.'}, {'id': 247, 'text': '"Felix welcomed her with rapturous joy, kissing her hands and smiling as I had never seen him smile before."', 'translation': '"Felix onu coşkulu bir sevinçle karşıladı; ellerini öperek ve daha önce hiç görmediğim şekilde gülümseyerek."', 'notes': 'rapturous joy: coşkun sevinç.'}, {'id': 248, 'text': '"Safie did not understand French, and Felix began to instruct her in reading and speaking the language."', 'translation': '"Safie Fransızca bilmiyordu ve Felix ona dili okumayı ve konuşmayı öğretmeye başladı."', 'notes': 'instruct in: ... konusunda eğitmek.'}, {'id': 249, 'text': '"I listened attentively to every lesson through my chink, learning to read alongside the foreign lady."', 'translation': '"Duvardaki yarığımdan her dersi pürdikkat dinledim; o yabancı hanımla birlikte okumayı öğrendim."', 'notes': 'listened attentively: dikkatle dinledi.'}, {'id': 250, 'text': '"They used Volney\'s Ruins of Empires as their textbook, which opened my mind to the history of mankind."', 'translation': '"Ders kitabı olarak Volney\'nin İmparatorlukların Yıkılışı eserini kullandılar; bu da zihnimi insanlık tarihine açtı."', 'notes': 'opened my mind: zihnimi açtı.'}, {'id': 251, 'text': '"I heard of the division of property, of immense wealth and squalid poverty; of rank, descent, and noble blood."', 'translation': '"Mülkiyetin bölünüşünü, muazzam servetleri ve sefil yoksulluğu; mevkileri, soy kütüklerini ve asil kanı öğrendim."', 'notes': 'squalid poverty: sefil yoksulluk.'}, {'id': 252, 'text': '"And what was I? Of my creation and creator I was absolutely ignorant; I possessed no money, no friends, no property."', 'translation': '"Peki ben neydim? Yaratılışımdan ve yaratıcımdan tamamen habersizdim; ne param vardı, ne dostum, ne de mülküm."', 'notes': 'what was I: ben neydim?'}, {'id': 253, 'text': '"I was endowed with a figure hideously deformed and loathsome; I was not even of the same nature as man."', 'translation': '"Korkunç derecede şekilsiz ve iğrenç bir endamla donatılmıştım; insanla aynı tabiata bile sahip değildim."', 'notes': 'hideously deformed: korkunç derecede şekilsiz.'}, {'id': 254, 'text': '"When I viewed my reflection in a clear pool, I drew back in horror, unable to believe that was myself."', 'translation': '"Berrak bir su birikintisinde kendi yansımamı gördüğümde dehşetle geri çekildim; onun ben olduğuma inanamayarak."', 'notes': 'drew back in horror: dehşetle geri çekildi.'}, {'id': 255, 'text': '"One night in the woods I found an abandoned leather portmanteau containing several books."', 'translation': '"Bir gece ormanda içinde birkaç kitap bulunan terk edilmiş deri bir bavul buldum."', 'notes': 'portmanteau: büyük deri seyahat çantası/bavul.'}, {'id': 256, 'text': '"They were Milton\'s Paradise Lost, Plutarch\'s Lives, and Goethe\'s Sorrows of Werter."', 'translation': '"Milton\'ın Kayıp Cennet\'i, Plutarkhos\'un Yaşamlar\'ı ve Goethe\'nin Genç Werther\'in Acıları kitaplarıydı bunlar."', 'notes': 'famous literary works: klasik başyapıtlar.'}, {'id': 257, 'text': '"I read these books with consuming eagerness, feeling every joy and agony of the human soul."', 'translation': '"Bu kitapları içimi kavuran bir hevesle okudum; insan ruhunun her bir neşesini ve ızdırabını hissederek."', 'notes': 'consuming eagerness: içini kemiren heves.'}, {'id': 258, 'text': '"Like Adam, I was united by no link to any other being in existence; but Adam came from the hands of God as a perfect creature."', 'translation': '"Tıpkı Adem gibi varlıktaki hiçbir canlıya hiçbir bağla bağlı değildim; fakat Adem Tanrı\'nın ellerinden kusursuz bir yaratık olarak çıkmıştı."', 'notes': 'united by no link: hiçbir bağla bağlı olmayan.'}, {'id': 259, 'text': '"I, alas, was wretched, helpless, and alone! Many times I considered Satan as the fitter emblem of my condition."', 'translation': '"Ben ise ne yazık ki sefildim, çaresizdim ve yapayalnızdım! Çoğu zaman Şeytan\'ı kendi durumuma daha uygun bir sembol saydım."', 'notes': 'fitter emblem: daha uygun simge.'}, {'id': 260, 'text': '"For often, like him, when I viewed the bliss of my protectors, the bitter gall of envy rose within my breast."', 'translation': '"Çünkü sık sık, tıpkı onun gibi koruyucularımın o saadetini izlediğimde, göğsümün içinde kıskançlığın acı zehri kabarırdı."', 'notes': 'bitter gall of envy: kıskançlığın acı safrası/zehri.'}]}, {'page_no': 14, 'title': 'The Bitter Rejection by the De Laceys', 'tr_title': 'De Lacey Kulübesindeki Acı Reddediliş ve Şiddet', 'vocab_focus': [('benevolent', 'hayırsever, iyi kalpli'), ('prejudice', 'önyargı'), ('rejection', 'reddedilme, kovulma'), ('blind', 'görme engelli'), ('stick', 'sopa, değnek'), ('horror', 'dehşet, yılgı'), ('despair', 'umutsuzluk, çaresizlik'), ('flee', 'kaçmak, firar etmek')], 'sentences': [{'id': 261, 'text': '"Spring advanced, and I resolved to execute my long-cherished plan of introducing myself to the cottagers,"', 'translation': '"İlkbahar ilerledi ve kendimi kulübe sakinlerine tanıtma yönündeki uzun süredir beslediğim planımı uygulamaya karar verdim,"', 'notes': 'long-cherished plan: uzun zamandır beslenen plan.'}, {'id': 262, 'text': '"I determined to enter the dwelling when the blind father was alone, hoping his lack of sight would save me from prejudice."', 'translation': '"Görme engeli beni önyargılardan korur umuduyla, kör baba yalnızken kulübeye girmeye karar verdim."', 'notes': 'lack of sight: görme yoksunluğu.'}, {'id': 263, 'text': '"One day, Felix, Agatha, and Safie departed on a long walk, leaving the venerable old man seated by the fire."', 'translation': '"Bir gün Felix, Agatha ve Safie saygıdeğer yaşlı adamı ateşin başında bırakarak uzun bir yürüyüşe çıktılar."', 'notes': 'venerable: saygıdeğer.'}, {'id': 264, 'text': '"My heart beat with sickening violence as I approached the door and knocked with trembling fingers."', 'translation': '"Kapıya yaklaşıp titreyen parmaklarımla vururken yüreğim mide bulandırıcı bir şiddetle çarpıyordu."', 'notes': 'sickening violence: mide bulandırıcı şiddet.'}, {'id': 265, 'text': '"Come in," said the old man gently, turning his sightless eyes toward the threshold.', 'translation': '"Giriniz," dedi yaşlı adam nazikçe, görmeyen gözlerini eşiğe doğru çevirerek.', 'notes': 'sightless eyes: görmeyen gözler.'}, {'id': 266, 'text': '"I entered and explained that I was a lonely traveler seeking food and a few minutes of rest."', 'translation': '"İçeri girdim ve yiyecek ve birkaç dakikalık dinlenme arayan yalnız bir gezgin olduğumu açıkladım."', 'notes': 'lonely traveler: yalnız gezgin.'}, {'id': 267, 'text': '"The old man welcomed me with sincere benevolence, placing bread and cheese before me upon the wooden table."', 'translation': '"Yaşlı adam samimi bir şefkatle beni karşıladı; ahşap masanın üzerine önüme ekmek ve peynir koydu."', 'notes': 'sincere benevolence: samimi iyilikseverlik.'}, {'id': 268, 'text': '"I poured out my overflowing heart, telling him of the virtuous friends I admired from afar."', 'translation': '"Taşan yüreğimi ona döktüm; uzaktan hayranlık duyduğum o erdemli dostlardan bahsettim."', 'notes': 'poured out heart: yüreğini döktü.'}, {'id': 269, 'text': '"I explained that a fatal prejudice made them fear me, though my soul was full of love and gratitude."', 'translation': '"Ruhum sevgi ve minnettarlıkla dolu olmasına rağmen, ölümcül bir önyargının onları benden korkuttuğunu açıkladım."', 'notes': 'fatal prejudice: ölümcül önyargı.'}, {'id': 270, 'text': '"Do not despair," said De Lacey. "To be friendless is indeed unfortunate, but human hearts are full of brotherly love."', 'translation': '"Umudunu yitirme," dedi De Lacey. "Dostsuz olmak sahiden talihsizliktir, fakat insan yüreği kardeşçe sevgiyle doludur."', 'notes': 'brotherly love: kardeşçe sevgi.'}, {'id': 271, 'text': '"Great God!" I cried, falling on my knees and seizing his withered hands. "You and your family are the friends I seek!"', 'translation': '"Yüce Tanrım!" diye haykırdım dizlerimin üzerine çöküp onun kurumuş ellerini kavrayarak. "Aradığım o dostlar sen ve senin ailendir!"', 'notes': 'withered hands: kurumuş/yaşlı eller.'}, {'id': 272, 'text': '"Do not cast me off! Protect me from the hatred of the world!"', 'translation': '"Beni başından atma! Beni dünyanın nefretinden koru!"', 'notes': 'cast off: başından savmak, terk etmek.'}, {'id': 273, 'text': 'At that very instant, the cottage door opened, and Felix, Agatha, and Safie stepped into the room.', 'translation': 'Tam o anda kulübenin kapısı açıldı ve Felix, Agatha ile Safie içeri adım attılar.', 'notes': 'stepped into: içeri adım attı.'}, {'id': 274, 'text': "Who can describe their horror and consternation on beholding me, a gigantic monster clutching their father's knees?", 'translation': 'Babalarının dizlerine sarılmış devasa bir canavarı, beni gördüklerindeki dehşet ve şaşkınlıklarını kim tarif edebilir?', 'notes': 'horror and consternation: dehşet ve şaşkınlık.'}, {'id': 275, 'text': 'Agatha fainted dead away upon the floor, while Safie rushed shrieking out of the cottage.', 'translation': 'Agatha kütük gibi yere yığılıp bayıldı; Safie ise çığlıklar atarak kulübeden dışarı kaçtı.', 'notes': 'fainted dead away: kendinden geçip bayıldı.'}, {'id': 276, 'text': "Felix darted forward with supernatural fury, tearing me violently from his father's arms.", 'translation': 'Felix doğaüstü bir öfkeyle öne fırladı; beni babasının kollarından şiddetle söküp aldı.', 'notes': 'darted forward: öne fırladı.'}, {'id': 277, 'text': 'With a stout cudgel, he struck me repeatedly about the head with merciless, crushing blows.', 'translation': 'Kalın bir sopayla, acımasız ve ezici darbelerle başıma peş peşe vurdu.', 'notes': 'stout cudgel: kalın sopa.'}, {'id': 278, 'text': 'I could have torn him limb from limb as easily as a lion rends an antelope, but my heart sank within me.', 'translation': 'Bir aslanın antilopu parçalaması gibi onu kolayca uzuv uzuv parçalayabilirdim, fakat yüreğim göğsümün içine çöktü.', 'notes': 'could have torn: parçalayabilirdim.'}, {'id': 279, 'text': 'Without retaliating, I broke from his blows and fled into the safety of my dark hovel.', 'translation': 'Karşılık vermeksizin darbelerinden sıyrıldım ve karanlık sundurmamın güvenliğine sığındım.', 'notes': 'without retaliating: misilleme yapmaksızın.'}, {'id': 280, 'text': 'My dream of love and fellowship was shattered; the gates of humanity were slammed shut in my face forever.', 'translation': 'Sevgi ve kardeşlik hayalim paramparça olmuştu; insanlığın kapıları yüzüme sonsuza dek küt diye kapanmıştı.', 'notes': 'slammed shut: küt diye kapandı.'}]}, {'page_no': 15, 'title': 'The Vow of Vengeance and the Burning Cottage', 'tr_title': 'Kulübenin Ateşe Verilmesi ve İnsan Irkına Savaş İlanı', 'vocab_focus': [('fury', 'öfke, hiddet'), ('howl', 'ulumak, feryat etmek'), ('torch', 'meşale'), ('inflame', 'tutuşturmak, ateşe vermek'), ('conflagration', 'büyük yangın'), ('extinguish', 'söndürmek'), ('warfare', 'savaş, muharebe'), ('revenge', 'intikam, öç')], 'sentences': [{'id': 281, 'text': '"When night fell, I rushed into the woods and gave vent to my anguish in wild, fearful shrieks."', 'translation': '"Gece çöktüğünde ormana koştum ve vahşi, korkunç çığlıklarla ızdırabımı haykırdım."', 'notes': 'gave vent to: dışa vurdu, saldı.'}, {'id': 282, 'text': '"I howled like a wild beast, tearing up trees and destroying everything in my path in uncontrollable madness."', 'translation': '"Yabani bir hayvan gibi uludum; ağaçları kökünden sökerek ve zapt edilemez bir delilikle yoluma çıkan her şeyi yerle bir ederek."', 'notes': 'howled like a beast: canavar gibi uludu.'}, {'id': 283, 'text': '"The cold stars shone in mockery; the moon seemed to laugh at my solitary, wretched misery."', 'translation': '"Soğuk yıldızlar alay edercesine parlıyordu; ay benim o yalnız ve bedbaht sefaletime güler gibiydi."', 'notes': 'shone in mockery: alayla parladı.'}, {'id': 284, 'text': '"I swore eternal hatred and vengeance against all mankind, and especially against the creator who formed me."', 'translation': '"Tüm insanlığa ve bilhassa beni vücuda getiren o yaratıcıya karşı ebedi bir nefret ve intikam yemini ettim."', 'notes': 'swore eternal hatred: ebedi nefret yemini etti.'}, {'id': 285, 'text': '"The next morning, I crept back to the cottage, hoping De Lacey might yet listen to my sorrowful plea."', 'translation': '"Ertesi sabah De Lacey belki hüzünlü yakarışımı dinler umuduyla kulübeye usulca geri süzüldüm."', 'notes': 'sorrowful plea: hüzünlü yakarış.'}, {'id': 286, 'text': '"The house was deserted; I heard Felix speaking to the landlord, declaring they could never live there again."', 'translation': '"Ev terk edilmişti; Felix\'in ev sahibiyle konuştuğunu, orada bir daha asla yaşayamayacaklarını bildirdiğini duydum."', 'notes': 'was deserted: terk edilmişti.'}, {'id': 287, 'text': '"They feared the monstrous demon who had entered their home, and fled the country forever."', 'translation': '"Evlerine giren o devasa iblisten korkmuşlar ve memleketi sonsuza dek terk etmişlerdi."', 'notes': 'fled the country: memleketten kaçtı.'}, {'id': 288, 'text': '"My last link to humanity was severed; from that moment despair gave place to burning fury."', 'translation': '"İnsanlıkla olan son bağım da kopmuştu; o andan itibaren umutsuzluk yerini kavurucu bir öfkeye bıraktı."', 'notes': 'gave place to: yerini ...e bıraktı.'}, {'id': 289, 'text': '"As night fell, I gathered dry brushwood and straw, piling them against the timber walls of the cottage."', 'translation': '"Gece çökerken kuru çalı çırpı ve saman topladım; onları kulübenin ahşap duvarlarına yığarak."', 'notes': 'dry brushwood: kuru çalı çırpı.'}, {'id': 290, 'text': '"I lit a torch from the embers of my fire and thrust it deep into the dry thatch of the roof."', 'translation': '"Ateşimin korlarından bir meşale yaktım ve onu çatının kuru samanlarına derinlemesine daldırdım."', 'notes': 'thrust deep: derine daldırdı.'}, {'id': 291, 'text': '"The flames sprang up with a crackling roar, licking the rafters and illuminating the dark forest with yellow fury."', 'translation': '"Alevler çıtırdayan bir kükremeyle yükseldi; kirişleri yaladı ve karanlık ormanı sarı bir gazapla aydınlattı."', 'notes': 'crackling roar: çıtırdayan kükreme.'}, {'id': 292, 'text': '"I danced around the conflagration in wild triumph, howling like a demon at the blazing ruins."', 'translation': '"Alevler içindeki harabelere bir iblis gibi uluyarak vahşi bir zafer sarhoşluğuyla yangının etrafında dans ettim."', 'notes': 'conflagration: büyük yangın.'}, {'id': 293, 'text': '"And now, with the world before me, where should I direct my vengeful steps?"', 'translation': '"Ve şimdi, önümde uzanan bu dünyada, intikam dolu adımlarımı nereye yöneltmeliydim?"', 'notes': 'vengeful steps: intikam dolu adımlar.'}, {'id': 294, 'text': '"In the pocket of the cloak I had taken from your laboratory, I found your scientific journal."', 'translation': '"Laboratuvarından aldığım pelerinin cebinde senin bilimsel günlüğünü bulmuştum."', 'notes': 'scientific journal: bilimsel günlük.'}, {'id': 295, 'text': '"I had learned to read it; it detailed the disgusting process of my creation and gave your name and city."', 'translation': '"Onu okumayı öğrenmiştim; yaratılışımın o iğrenç sürecini ayrıntılarıyla anlatıyor, adını ve şehrini veriyordu."', 'notes': 'disgusting process: iğrenç süreç.'}, {'id': 296, 'text': '"Geneva! There lived my creator, the author of my misery, upon whom I would take bloody revenge!"', 'translation': '"Cenevre! Benim yaratıcım, sefaletimin müsebbibi orada yaşıyordu; ondan kanlı bir intikam alacaktım!"', 'notes': 'author of misery: sefaletin müsebbibi.'}, {'id': 297, 'text': '"I travelled only by night, avoiding the sight of men, hiding in dark caves during the blazing daylight."', 'translation': '"İnsanların bakışlarından kaçınarak yalnızca gece yol aldım; yakıcı gün ışığında karanlık mağaralarda saklanarak."', 'notes': 'blazing daylight: yakıcı gün ışığı.'}, {'id': 298, 'text': '"Once, in a forest, I rescued a young girl from drowning in a swollen, rushing torrent."', 'translation': '"Bir keresinde ormanda, coşkun ve kabarmış bir akıntıda boğulmakta olan küçük bir kızı kurtardım."', 'notes': 'swollen torrent: kabarmış akıntı.'}, {'id': 299, 'text': '"Her rustic companion rushed up, tore the girl from my arms, and shot me in the shoulder with his gun!"', 'translation': '"Köylü arkadaşı koşup geldi; kızı kollarımdan kopardı ve tüfeğiyle beni omzumdan vurdu!"', 'notes': 'shot in the shoulder: omzundan vurdu.'}, {'id': 300, 'text': '"This was the reward of my benevolence! I writhed in agony, vowing eternal war against the human race!"', 'translation': '"İyilikseverliğimin mükafatı işte buydu! Izdırapla kıvrandım; insan ırkına karşı ebedi bir savaş ilan ettim!"', 'notes': 'writhed in agony: acıyla kıvrandı.'}]}, {'page_no': 16, 'title': 'The Fatal Encounter with William and the Portrait', 'tr_title': 'William ile Karşılaşma ve Çerçevelenen Madalyon', 'vocab_focus': [('monster', 'canavar'), ('strangle', 'boğarak öldürmek'), ('portrait', 'minyatür portre'), ('locket', 'madalyon'), ('barn', 'samanlık, ahır'), ('revenge', 'intikam'), ('slumber', 'uyku, uyuklama'), ('corpse', 'ceset')], 'sentences': [{'id': 301, 'text': '"After months of painful journeying, I arrived at last in the neighbourhood of Geneva."', 'translation': '"Aylar süren acılı bir yolculuğun ardından nihayet Cenevre civarına ulaştım."', 'notes': 'painful journeying: acılı yolculuk.'}, {'id': 302, 'text': '"It was evening; I hid myself among the fields of Plainpalais, resting my weary limbs."', 'translation': '"Akşamdı; yorgun uzuvlarımı dinlendirerek Plainpalais tarlalarının arasına gizlendim."', 'notes': 'weary limbs: yorgun kollar bacaklar.'}, {'id': 303, 'text': '"Suddenly, a beautiful child came running into my hiding place, playing merrily with childish glee."', 'translation': '"Ansızın, çocukça bir neşeyle şen şakrak oynayarak güzel bir çocuk saklandığım yere doğru koşageldi."', 'notes': 'childish glee: çocukça neşe.'}, {'id': 304, 'text': '"The idea seized me that this little boy was too young to have formed prejudices against deformity."', 'translation': '"Bu küçük çocuğun çirkinliğe karşı önyargılar geliştirmek için henüz çok genç olduğu fikri aklıma düştü."', 'notes': 'idea seized me: aklıma fikir geldi.'}, {'id': 305, 'text': '"I thought I could seize him, educate him as my companion, and no longer be solitary upon this earth."', 'translation': '"Onu yakalayıp kendime yoldaş olarak eğitebileceğimi ve bu dünyada artık yapayalnız kalmayacağımı düşündüm."', 'notes': 'as my companion: yoldaşım olarak.'}, {'id': 306, 'text': '"I sprang from my concealment and caught the boy by the arm."', 'translation': '"Saklandığım yerden fırladım ve çocuğu kolundan yakaladım."', 'notes': 'sprang from concealment: saklandığı yerden fırladı.'}, {'id': 307, 'text': '"As soon as he beheld me, he placed his small hands before his eyes and screamed loudly in terror."', 'translation': '"Beni görür görmez küçük ellerini gözlerinin önüne koydu ve dehşet içinde avaz avaz çığlık attı."', 'notes': 'screamed in terror: dehşetle çığlık attı.'}, {'id': 308, 'text': '"Child, what is the matter?" I said. "I do not intend to hurt you; listen to me!"', 'translation': '"Çocuk, neyin var?" dedim. "Sana zarar verme niyetim yok; dinle beni!"', 'notes': 'intend to hurt: incitme niyetinde olmak.'}, {'id': 309, 'text': '"Monster! Ugly wretch!" he cried, struggling wildly. "Let me go! You want to eat me and tear me to pieces!"', 'translation': '"Canavar! Çirkin sefil!" diye bağırdı delicesine çırpınarak. "Bırak beni! Beni yemek ve parçalamak istiyorsun!"', 'notes': 'struggling wildly: çılgınca çırpınarak.'}, {'id': 310, 'text': '"My papa is a syndic—he is M. Frankenstein—he will punish you! He will send you to jail!"', 'translation': '"Benim babam yargıçtır—o M. Frankenstein\'dır—seni cezalandırır! Seni zindana attırır!"', 'notes': 'syndic: yargıç, meclis üyesi.'}, {'id': 311, 'text': '"Frankenstein!" I exclaimed. "You belong then to my enemy—to him toward whom I have sworn eternal vengeance!"', 'translation': '"Frankenstein mı!" diye haykırdım. "Demek sen benim düşmanıma aitsin—ebedi intikam yemini ettiğim o adama!"', 'notes': 'sworn eternal vengeance: ebedi intikam yemini etti.'}, {'id': 312, 'text': '"The child struggled and loaded me with epithets which carried despair to my heart."', 'translation': '"Çocuk çırpındı ve yüreğime umutsuzluk taşıyan hakaretleri peş peşe yüzüme savurdu."', 'notes': 'loaded with epithets: hakaretler yağdırdı.'}, {'id': 313, 'text': '"I grasped his throat to silence his cries, and in a moment he lay dead at my feet!"', 'translation': '"Çığlıklarını susturmak için gırtlağını kavradım ve bir anda ayaklarımın dibinde cansız serildi!"', 'notes': 'grasped throat: gırtlağını kavradı.'}, {'id': 314, 'text': '"I gazed on my victim, and my heart swelled with savage exultation and grim triumph."', 'translation': '"Kurbanıma baktım ve yüreğim vahşi bir sevinçle, karanlık bir zafer duygusuyla kabardı."', 'notes': 'savage exultation: vahşi sevinç.'}, {'id': 315, 'text': '"I clapped my hands and cried: \'I too can create desolation; my enemy is not invulnerable!\'"', 'translation': '"Ellerimi birbirine çırptım ve haykırdım: \'Ben de yıkım yaratabiliyorum işte; düşmanım dokunulmaz değilmiş!\'"', 'notes': 'create desolation: yıkım yaratmak.'}, {'id': 316, 'text': '"Looking on the dead child, I saw a miniature locket hanging around his neck."', 'translation': '"Ölü çocuğa baktığımda, boynunda asılı duran minyatür bir madalyon gördüm."', 'notes': 'miniature locket: minyatür madalyon.'}, {'id': 317, 'text': '"It was the portrait of a most lovely woman, smiling with angelic sweetness."', 'translation': '"Meleksi bir tatlılıkla gülümseyen son derece güzel bir kadının portresiydi bu."', 'notes': 'angelic sweetness: meleksi tatlılık.'}, {'id': 318, 'text': '"I took it, and wandering into a nearby barn, I found a young woman sleeping peacefully in the straw."', 'translation': '"Onu aldım ve yakındaki bir samanlığa sığınırken samanın içinde huzurla uyuyan genç bir kadın buldum."', 'notes': 'sleeping peacefully: huzurla uyuyan.'}, {'id': 319, 'text': '"Here was one of that race which despised me; I slipped the locket into the folds of her dress."', 'translation': '"İşte benden nefret eden o ırkın bir ferdi yatıyordu; madalyonu elbisesinin kıvrımlarının içine usulca sokuverdim."', 'notes': 'slipped into folds: kıvrımların içine soktu.'}, {'id': 320, 'text': '"She should suffer for the murder, and thus I struck another deadly blow against my creator!"', 'translation': '"Cinayetin cezasını o çekmeliydi ve böylece yaratıcıma ölümcül bir darbe daha indirmiş oldum!"', 'notes': 'struck deadly blow: ölümcül darbe indirdi.'}]}, {'page_no': 17, 'title': "The Creature's Demands on the Glacier", 'tr_title': 'Buzul Üzerindeki Talepler ve Şartlar', 'vocab_focus': [('malicious', 'kötü niyetli, hain'), ('misery', 'sefalet, ıstırap'), ('companion', 'yoldaş, eş'), ('desert', 'ıssız çöl, yaban'), ('deed', 'eylem, amel'), ('refusal', 'reddetme, ret'), ('species', 'tür'), ('exile', 'sürgün')], 'sentences': [{'id': 321, 'text': '"I am malicious only because I am completely miserable," the creature proclaimed with fierce passion.', 'translation': '"Ben sadece ve sadece son derece sefil ve bahtsız olduğum için kötüyüm," diye haykırdı yaratık ateşli bir tutkuyla.', 'notes': 'fierce passion: şiddetli tutku.'}, {'id': 322, 'text': '"Every human being hates me, drives me away, and treats me as an abhorrent fiend."', 'translation': '"Her insan benden nefret ediyor, beni kovuyor ve bana iğrenç bir iblis muamelesi yapıyor."', 'notes': 'abhorrent fiend: iğrenç iblis.'}, {'id': 323, 'text': '"If any human loved me or showed me kindness, I would return it with endless gratitude."', 'translation': '"Eğer herhangi bir insan beni sevseydi ya da bana şefkat gösterseydi, buna sonsuz bir minnetle karşılık verirdim."', 'notes': 'endless gratitude: sonsuz minnettarlık.'}, {'id': 324, 'text': '"Shall I not then hate those who spurn and despise my peaceful heart?"', 'translation': '"O halde benim barışçıl kalbimi hor gören ve dışlayanlardan nefret etmeyeyim mi?"', 'notes': 'spurn and despise: hor görmek ve dışlamak.'}, {'id': 325, 'text': '"You must create a female companion for me, one of the same species and deformed like myself!"', 'translation': '"Bana benimle aynı türden ve benim gibi biçimsiz bir dişi yoldaş yaratmalısın!"', 'notes': 'female companion: dişi yoldaş / eş.'}, {'id': 326, 'text': '"She alone will understand my suffering, and we shall share an innocent, peaceful life together."', 'translation': '"Yalnızca o benim çektiğim acıları anlayabilir ve birlikte masum, huzurlu bir hayatı paylaşabiliriz."', 'notes': 'peaceful life: huzurlu yaşam.'}, {'id': 327, 'text': 'Victor listened with a mixture of immense horror and profound bewilderment.', 'translation': 'Victor bu sözleri derin bir dehşet ve büyük bir şaşkınlık karışımıyla dinledi.', 'notes': 'profound bewilderment: derin şaşkınlık.'}, {'id': 328, 'text': '"I will never grant your monstrous request," Victor cried out angrily.', 'translation': '"Senin bu korkunç isteğini asla kabul etmeyeceğim," diye öfkeyle haykırdı Victor.', 'notes': 'monstrous request: canavarca talep.'}, {'id': 329, 'text': '"You would join together in cruelty and desolate the entire world with wicked vengeance!"', 'translation': '"Zalimlikte birleşir ve kötücül bir intikamla bütün dünyayı harabeye çevirirsiniz!"', 'notes': 'desolate the entire world: tüm dünyayı harabeye çevirmek.'}, {'id': 330, 'text': '"You are mistaken, creator," the daemon replied with earnest solemnity.', 'translation': '"Yanılıyorsun, yaratıcım," diye yanıt verdi iblis samimi bir ciddiyetle.', 'notes': 'earnest solemnity: samimi ciddiyet.'}, {'id': 331, 'text': '"Our mutual sympathy will soften our hearts and extinguish every spark of malice."', 'translation': '"Karşılıklı şefkatimiz kalplerimizi yumuşatacak ve içimizdeki her kötülük kıvılcımını söndürecektir."', 'notes': 'extinguish spark: kıvılcımı söndürmek.'}, {'id': 332, 'text': '"If you grant my prayer, we will depart forever from the neighborhoods of civilized men."', 'translation': '"Eğer bu yakarışımı kabul edersen, medeni insanların yaşadığı diyarlardan sonsuza dek ayrılacağız."', 'notes': 'civilized men: medeni insanlar.'}, {'id': 333, 'text': '"We will make our home in the vast and wild deserts of South America, away from all mankind."', 'translation': '"Bütün insanlıktan uzakta, Güney Amerika\'nın uçsuz bucaksız ve vahşi ıssızlıklarında yuvamızı kuracağız."', 'notes': 'vast and wild deserts: uçsuz bucaksız vahşi topraklar/çöller.'}, {'id': 334, 'text': '"We will eat acorns and berries, sleeping beneath the open sky without harming any living creature."', 'translation': '"Palamut ve yabani meyveler yiyecek, hiçbir canlıya zarar vermeden açık gökyüzü altında uyuyacağız."', 'notes': 'beneath open sky: açık gökyüzü altında.'}, {'id': 335, 'text': '"The sun will shine on us as pleasantly as on you, and our lives will pass in tranquil peace."', 'translation': '"Güneş sizin üzerinize olduğu gibi bizim üzerimize de hoşça parlayacak ve hayatımız dingin bir barış içinde akıp gidecek."', 'notes': 'tranquil peace: dingin barış/huzur.'}, {'id': 336, 'text': '"But if you refuse, I will shower ruin upon your loved ones until your life is destroyed."', 'translation': '"Fakat reddedersen, senin hayatın tamamen mahvolana dek sevdiklerinin üzerine felaketler yağdıracağım."', 'notes': 'shower ruin: felaket yağdırmak.'}, {'id': 337, 'text': 'Victor stared at the wretched giant, feeling deeply moved by his sincere and tragic plea.', 'translation': 'Victor bu zavallı deve baktı ve onun içten ve trajik yalvarışı karşısında derinden sarsıldı.', 'notes': 'deeply moved: derinden etkilenmiş/sarsılmış.'}, {'id': 338, 'text': 'Did Victor not owe his creation some small degree of happiness after causing such utter torment?', 'translation': 'Victor böylesine mutlak bir ızdıraba yol açtıktan sonra yarattığı varlığa bir nebze olsun mutluluk borçlu değil miydi?', 'notes': 'utter torment: mutlak eziyet/ıstırap.'}, {'id': 339, 'text': '"Do you swear to leave Europe forever the moment your companion is brought to life?" Victor asked solemnly.', 'translation': '"Yoldaşın hayata kavuşturulduğu an Avrupa\'yı sonsuza dek terk edeceğine yemin ediyor musun?" diye ciddiyetle sordu Victor.', 'notes': 'brought to life: hayata döndürüldüğünde.'}, {'id': 340, 'text': '"I swear by the eternal sun and the sacred fire of life," the creature vowed, and vanished swiftly into the fog.', 'translation': '"Ebedi güneş ve hayatın kutsal ateşi üzerine yemin ederim," diye ant içti yaratık ve sisin içinde hızla kayboldu.', 'notes': 'sacred fire of life: hayatın kutsal ateşi.'}]}, {'page_no': 18, 'title': 'Journey to Britain and the Haunting Burden', 'tr_title': 'Britanya Yolculuğu ve Peşini Bırakmayan Lanet', 'vocab_focus': [('undertaking', 'girişim, zorlu görev'), ('postpone', 'ertelemek'), ('melancholy', 'hüzün, keder'), ('distraction', 'dikkat dağıtıcı şey, avuntu'), ('reluctance', 'isteksizlik, gönülsüzlük'), ('laboratory', 'laboratuvar'), ('secluded', 'gözlerden uzak, tenha'), ('barren', 'çorak, verimsiz')], 'sentences': [{'id': 341, 'text': 'Victor descended Montanvert and returned to Geneva with a heavy heart and trembling limbs.', 'translation': "Victor Montanvert dağından indi ve ağır bir yürek ve titreyen bacaklarla Cenevre'ye döndü.", 'notes': 'heavy heart: ağırlaşmış/hüzünlü yürek.'}, {'id': 342, 'text': 'The dreadful promise he had made weighed upon his mind like a suffocating dark cloud.', 'translation': 'Verdiği o korkunç söz, zihnine boğucu karanlık bir bulut gibi ağırlık yapıyordu.', 'notes': 'suffocating dark cloud: boğucu kara bulut.'}, {'id': 343, 'text': "His father, noticing Victor's perpetual melancholy, gently suggested that he should marry Elizabeth.", 'translation': "Victor'ın dinmeyen hüznünü fark eden babası, nazikçe Elizabeth ile evlenmesini önerdi.", 'notes': 'perpetual melancholy: dinmeyen hüzün.'}, {'id': 344, 'text': '"Nothing in this world would bring me greater joy than our union," Victor replied softly.', 'translation': '"Bu dünyada hiçbir şey bana birleşmemizden daha büyük bir neşe getiremez," diye usulca yanıtladı Victor.', 'notes': 'union: birleşme, evlilik.'}, {'id': 345, 'text': '"However, I must first undertake a journey to England to complete some scientific inquiries."', 'translation': '"Ancak bazı bilimsel araştırmaları tamamlamak için önce İngiltere\'ye bir yolculuk yapmalıyım."', 'notes': 'scientific inquiries: bilimsel araştırmalar/incelemeler.'}, {'id': 346, 'text': 'Victor could not bear the thought of marrying his beloved while this repulsive obligation hung over him.', 'translation': 'Victor, tepesinde bu itici ve iğrenç yükümlülük asılı dururken sevdiği kadınla evlenme fikrine katlanamıyordu.', 'notes': 'repulsive obligation: itici yükümlülük.'}, {'id': 347, 'text': 'He needed to consult certain English philosophers who possessed new discoveries relevant to his work.', 'translation': 'Çalışmasıyla ilgili yeni keşiflere sahip belirli İngiliz doğa bilginlerine danışması gerekiyordu.', 'notes': 'consult philosophers: bilginlere danışmak.'}, {'id': 348, 'text': 'To his surprise and relief, his dear friend Henry Clerval joined him for the long journey.', 'translation': 'Hem şaşkınlık hem de rahatlama vesilesi olarak, sevgili dostu Henry Clerval bu uzun yolculukta ona katıldı.', 'notes': 'to his surprise and relief: şaşkınlığı ve rahatlamasıyla birlikte.'}, {'id': 349, 'text': 'Clerval was full of youthful joy, admiring the majestic castles and green rolling hills of the Rhine.', 'translation': "Clerval gençlik neşesiyle doluydu; Ren Nehri'nin görkemli şatolarına ve yemyeşil dalgalı tepelerine hayranlıkla bakıyordu.", 'notes': 'youthful joy: gençlik neşesi.'}, {'id': 350, 'text': 'Victor, by contrast, felt like a condemned criminal walking towards a waiting scaffold.', 'translation': 'Victor ise tam aksine, kendisini bekleyen darağacına doğru yürüyen idama mahkûm bir suçlu gibi hissediyordu.', 'notes': 'waiting scaffold: bekleyen darağacı.'}, {'id': 351, 'text': 'They arrived in London during the autumn and spent several months visiting historic monuments and scholars.', 'translation': "Sonbaharda Londra'ya vardılar ve birkaç ayı tarihi anıtları ve akademisyenleri ziyaret ederek geçirdiler.", 'notes': 'historic monuments: tarihi anıtlar.'}, {'id': 352, 'text': 'Yet Victor could never forget the invisible shadow following his every movement.', 'translation': 'Fakat Victor, attığı her adımı takip eden o görünmez gölgeyi bir an olsun aklından çıkaramıyordu.', 'notes': 'invisible shadow: görünmez gölge.'}, {'id': 353, 'text': 'He knew the daemon was tracking him from the shadows, watching for the fulfillment of the oath.', 'translation': 'İblisin onu gölgelerden izlediğini ve verilen yeminin yerine getirilmesini beklediğini biliyordu.', 'notes': 'fulfillment of oath: yeminin yerine getirilmesi.'}, {'id': 354, 'text': 'In the spring, they traveled northward into the wild and rugged highlands of Scotland.', 'translation': "İlkbaharda, İskoçya'nın vahşi ve sarp dağlık arazilerine doğru kuzeye yöneldiler.", 'notes': 'rugged highlands: sarp dağlık araziler.'}, {'id': 355, 'text': "Victor felt that he could not bear Henry's cheerful presence while performing his unholy task.", 'translation': "Victor o lanetli görevini icra ederken Henry'nin neşeli varlığına tahammül edemeyeceğini hissetti.", 'notes': 'unholy task: kutsal olmayan, lanetli görev.'}, {'id': 356, 'text': '"Leave me alone for a few weeks, dear Henry, while I explore the distant islands," Victor begged.', 'translation': '"Sevgili Henry, ben uzak adaları keşfederken beni birkaç hafta yalnız bırak," diye yalvardı Victor.', 'notes': 'distant islands: uzak adalar.'}, {'id': 357, 'text': 'Clerval agreed reluctantly, promising to wait for Victor in the Scottish town of Perth.', 'translation': "Clerval gönülsüzce razı oldu ve Victor'ı İskoçya'nın Perth kasabasında bekleyeceğine söz verdi.", 'notes': 'agreed reluctantly: gönülsüzce kabul etti.'}, {'id': 358, 'text': 'Victor journeyed alone to the northernmost Orkney Islands, a remote and desolate archipelago.', 'translation': "Victor tek başına en kuzeydeki Orkney Adaları'na, ıssız ve ücra bir takımadaya doğru yol aldı.", 'notes': 'desolate archipelago: ıssız takımada.'}, {'id': 359, 'text': 'On a tiny, barren rock inhabited by only three impoverished fishermen, Victor rented a filthy two-room hut.', 'translation': 'Sadece üç yoksul balıkçının yaşadığı küçücük, çorak bir kayalıkta Victor iki odalı döküntü bir kulübe kiraladı.', 'notes': 'impoverished fishermen: yoksul balıkçılar.'}, {'id': 360, 'text': 'In this secluded shack, overlooking the cold and stormy northern sea, Victor set up his lonely laboratory.', 'translation': 'Kuzeyin soğuk ve fırtınalı denizine bakan bu izbe kulübede Victor yalnız laboratuvarını kurdu.', 'notes': 'secluded shack: gözlerden uzak baraka/kulübe.'}]}, {'page_no': 19, 'title': "The Destroyed Creation and the Fiend's Curse", 'tr_title': 'Yok Edilen Yaratılış ve Canavarın Laneti', 'vocab_focus': [('loathsome', 'iğrenç, tiksindirici'), ('remorse', 'vicdan azabı, pişmanlık'), ('malice', 'kötülük, garez'), ('offspring', 'yavru, nesil, soy'), ('destruction', 'yıkım, yok ediş'), ('treachery', 'ihanet, kalleşlik'), ('glare', 'öfkeli bakış'), ('vengeance', 'intikam, öç')], 'sentences': [{'id': 361, 'text': 'Victor commenced his loathsome labor with trembling fingers and a sickening sense of dread.', 'translation': 'Victor o iğrenç işe titreyen parmaklar ve midesini bulandıran bir dehşet hissiyle başladı.', 'notes': 'loathsome labor: iğrenç uğraş/emek.'}, {'id': 362, 'text': 'Gathering materials had been horrifying, but assembling this second creation felt infinitely worse.', 'translation': 'Malzemeleri toplamak korkunçtu ama bu ikinci varlığı birleştirmek katbekat daha berbat hissettiriyordu.', 'notes': 'assembling creation: yaratımı bir araya getirmek.'}, {'id': 363, 'text': 'Days and weeks slipped away as he worked in utter isolation beneath the howling northern gales.', 'translation': 'Kuzeyin uğuldayan fırtınaları altında mutlak bir tecrit içinde çalışırken günler ve haftalar akıp gitti.', 'notes': 'howling northern gales: uğuldayan kuzey fırtınaları.'}, {'id': 364, 'text': 'One cold night, while sitting alone in his workshop, profound philosophical doubts assailed his mind.', 'translation': 'Soğuk bir gece atölyesinde tek başına otururken, zihnini derin felsefi şüpheler kuşattı.', 'notes': 'profound doubts: derin şüpheler.'}, {'id': 365, 'text': 'What if this new female creature proved to be ten times more wicked and violent than her companion?', 'translation': 'Ya bu yeni dişi yaratık yoldaşından on kat daha kötücül ve şiddet yanlısı çıkarsa ne olacaktı?', 'notes': 'wicked and violent: kötücül ve şiddet dolu.'}, {'id': 366, 'text': 'She had made no promise to withdraw into the uninhabited wilderness of South America.', 'translation': "O dişi varlık, Güney Amerika'nın kimsesiz ıssızlıklarına çekilmek konusunda hiçbir söz vermemişti.", 'notes': 'uninhabited wilderness: yerleşim olmayan yaban.'}, {'id': 367, 'text': 'They might loathe each other, or they might breed a terrible race of devils upon the earth!', 'translation': 'Birbirlerinden tiksinebilirlerdi ya da yeryüzünde korkunç bir şeytanlar ırkı türetebilirlerdi!', 'notes': 'breed a race of devils: şeytanlar ırkı türetmek.'}, {'id': 368, 'text': 'A whole generation of demonic monsters could eventually destroy the entire human race.', 'translation': 'İblis benzeri canavarlardan oluşan koca bir nesil en sonunda tüm insan ırkını yok edebilirdi.', 'notes': 'demonic monsters: iblis canavarlar.'}, {'id': 369, 'text': 'Had Victor any moral right to inflict such a dreadful curse upon future generations of mankind?', 'translation': "Victor'ın insanlığın gelecek nesillerinin başına böylesi korkunç bir lanet sarmaya ahlaki bir hakkı var mıydı?", 'notes': 'inflict curse: lanet yağdırmak/musallat etmek.'}, {'id': 370, 'text': 'Suddenly, Victor looked up and saw the moon rising above the restless and churning ocean waves.', 'translation': 'Ansızın Victor başını kaldırdı ve ayın çalkantılı ve kabaran okyanus dalgalarının üzerinde yükseldiğini gördü.', 'notes': 'churning ocean waves: çalkalanan okyanus dalgaları.'}, {'id': 371, 'text': 'In the pale moonlight at the open window, a ghastly face appeared, grinning with malicious triumph.', 'translation': 'Açık pencereden vuran soluk ay ışığında, kötücül bir zaferle sırıtan korkunç bir yüz belirdi.', 'notes': 'ghastly face: korkunç/hortlak gibi yüz.'}, {'id': 372, 'text': 'It was the daemon, who had followed Victor across land and sea to observe his progress!', 'translation': "Gelişmeleri izlemek için karaları ve denizleri aşarak Victor'ı takip eden o iblisti bu!", 'notes': 'observe progress: ilerlemeyi gözlemlemek.'}, {'id': 373, 'text': "The creature's yellow eyes gleamed with unnatural malice and wild, impatient expectation.", 'translation': 'Yaratığın sarı gözleri doğal olmayan bir garez ve vahşi, sabırsız bir beklentiyle parıldıyordu.', 'notes': 'impatient expectation: sabırsız beklenti.'}, {'id': 374, 'text': 'Overcome with righteous fury and moral disgust, Victor tore the unfinished female creature into shreds.', 'translation': 'Haklı bir öfke ve ahlaki bir tiksintiyle dolup taşan Victor, henüz tamamlanmamış dişi yaratığı parça pinçik etti.', 'notes': 'tore into shreds: paramparça etti.'}, {'id': 375, 'text': 'The monster uttered a shriek of howling despair and vanished instantly into the pitch-black night.', 'translation': 'Canavar feryat figan eden bir çaresizlik çığlığı kopardı ve zifiri karanlık gecede anında gözden kayboldu.', 'notes': 'howling despair: inleyen/feryat eden çaresizlik.'}, {'id': 376, 'text': 'Several hours later, while Victor sat weeping over the scattered remains, he heard soft footsteps approach.', 'translation': 'Birkaç saat sonra Victor etrafa saçılmış kalıntıların başında ağlarken, yumuşak ayak seslerinin yaklaştığını işitti.', 'notes': 'scattered remains: etrafa saçılmış kalıntılar.'}, {'id': 377, 'text': 'The door creaked open, and the towering daemon stepped inside, his face distorted with terrifying fury.', 'translation': 'Kapı gıcırdayarak açıldı ve heybetli iblis korkunç bir öfkeyle çarpılmış yüzüyle içeri adım attı.', 'notes': 'distorted with fury: öfkeyle çarpılmış/şekil değiştirmiş.'}, {'id': 378, 'text': '"You have broken your sacred promise," the monster hissed in a voice cold as glacial ice.', 'translation': '"Kutsal sözünü çiğnedin," diye tısladı canavar buzul buzu kadar soğuk bir sesle.', 'notes': 'hissed: tısladı.'}, {'id': 379, 'text': '"Do you dare to destroy my hopes of love and condemn me to eternal misery?"', 'translation': '"Aşk ümitlerimi yok etmeye ve beni ebedi bir sefalete mahkûm etmeye nasıl cüret edersin?"', 'notes': 'eternal misery: ebedi sefalet.'}, {'id': 380, 'text': '"Remember this well, proud creator: I shall be with you on your wedding-night!"', 'translation': '"Bunu iyi belle, kibirli yaratıcı: Düğün gecende seninle olacağım!"', 'notes': 'wedding-night: düğün gecesi.'}]}, {'page_no': 20, 'title': 'The Murder of Henry Clerval in Ireland', 'tr_title': "İrlanda Kıyısında Henry Clerval'ın Katli", 'vocab_focus': [('rowboat', 'kayık, sandal'), ('drifting', 'sürüklenme'), ('tempest', 'fırtına, kasırga'), ('magistrate', 'yargıç, sulh hakimi'), ('accusation', 'suçlama, itham'), ('strangled', 'boğulmuş'), ('corpse', 'ceset'), ('delirium', 'sayıklama, hezeyan')], 'sentences': [{'id': 381, 'text': 'With those chilling words echoing in the empty room, the fiend bounded out and disappeared.', 'translation': 'O dondurucu sözler boş odada yankılanırken iblis dışarı fırladı ve kayboldu.', 'notes': 'chilling words: kan dondurucu sözler.'}, {'id': 382, 'text': 'Victor fell to his knees in horror, knowing that his own death was promised on his future wedding night.', 'translation': 'Gelecekteki düğün gecesinde kendi ölümünün vadedildiğini anlayan Victor dehşet içinde dizlerinin üzerine çöktü.', 'notes': 'fell to his knees: dizlerinin üzerine çöktü.'}, {'id': 383, 'text': 'The following morning, Victor packed the torn remnants of the creature into a heavy basket weighted with stones.', 'translation': 'Ertesi sabah Victor yaratığın parçalanmış kalıntılarını taşlarla ağırlaştırılmış büyük bir sepete doldurdu.', 'notes': 'torn remnants: parçalanmış kalıntılar.'}, {'id': 384, 'text': 'At midnight, he boarded a small rowboat and sailed out into the deep waters of the turbulent sea.', 'translation': 'Gece yarısı küçük bir sandala bindi ve çalkantılı denizin derin sularına doğru açıldı.', 'notes': 'turbulent sea: çalkantılı deniz.'}, {'id': 385, 'text': 'With a heavy splash, he cast the basket into the depths, watching it sink forever into the ocean abyss.', 'translation': 'Ağır bir şapırtıyla sepeti sulara bıraktı ve okyanusun derinliklerinde ebediyen batışını seyretti.', 'notes': 'ocean abyss: okyanus uçurumu/derinliği.'}, {'id': 386, 'text': 'Exhausted by days of agony, Victor fell asleep on the bottom of the boat while the gentle waves rocked him.', 'translation': 'Günler süren azapla tükenen Victor, nazik dalgalar kendisini sallarken kayığın tabanında uyuyakaldı.', 'notes': 'exhausted by agony: ızdıraptan tükenmiş.'}, {'id': 387, 'text': 'When he woke up at dawn, a violent tempest had arisen, driving his small vessel far across the sea.', 'translation': 'Şafakta uyandığında şiddetli bir fırtına kopmuştu ve küçük teknesini denizin fersahlarca ötesine sürüklüyordu.', 'notes': 'violent tempest: şiddetli fırtına/kasırga.'}, {'id': 388, 'text': 'For many frightening hours, Victor battled the raging storm without food, water, or a compass.', 'translation': 'Korku dolu saatler boyunca Victor yiyeceksiz, susuz ve pusulasız olarak azgın fırtınayla boğuştu.', 'notes': 'raging storm: azgın fırtına.'}, {'id': 389, 'text': 'Late that afternoon, the wind finally drove his battered boat toward an unfamiliar rocky harbor.', 'translation': 'O öğleden sonrasının geç saatlerinde rüzgâr nihayet hırpalanmış teknesini bilmediği kayalık bir limana sürükledi.', 'notes': 'battered boat: hırpalanmış kayık.'}, {'id': 390, 'text': 'As soon as his boat touched the shore, a crowd of hostile and suspicious villagers surrounded him.', 'translation': 'Teknesi kıyıya değer değmez, düşmanca ve şüpheci köylülerden oluşan bir kalabalık etrafını sardı.', 'notes': 'hostile and suspicious: düşmanca ve şüpheci.'}, {'id': 391, 'text': '"You must come with us to the local magistrate, Mr. Kirwin," a rough fisherman demanded sternly.', 'translation': '"Bizimle yerel sulh yargıcı Bay Kirwin\'e gelmelisiniz," diye sertçe talep etti kaba bir balıkçı.', 'notes': 'local magistrate: yerel sulh yargıcı.'}, {'id': 392, 'text': '"A brutal murder was committed on our coast last night, and you must give an account of yourself."', 'translation': '"Dün gece kıyımızda vahşi bir cinayet işlendi ve kendinizi açıklamak zorundasınız."', 'notes': 'give an account of yourself: kendini açıklamak, hesap vermek.'}, {'id': 393, 'text': 'Victor was taken to the courtroom, feeling entirely calm, for he believed his innocence was beyond question.', 'translation': 'Masumiyetinin tartışılmaz olduğuna inandığı için Victor gayet sakin bir şekilde mahkeme salonuna götürüldü.', 'notes': 'beyond question: şüphe götürmez.'}, {'id': 394, 'text': 'Magistrate Kirwin spoke with grave solemnity: "A handsome young gentleman was discovered strangled near the beach."', 'translation': 'Yargıç Kirwin ağırbaşlı bir ciddiyetle konuştu: "Kumsalın yakınında boğulmuş yakışıklı genç bir beyefendi bulundu."', 'notes': 'discovered strangled: boğulmuş halde bulundu.'}, {'id': 395, 'text': "Kirwin led Victor into an adjoining bedchamber to observe his reaction upon seeing the dead man's body.", 'translation': "Kirwin, cesedi gördüğündeki tepkisini gözlemlemek için Victor'ı bitişikteki yatak odasına götürdü.", 'notes': 'adjoining bedchamber: bitişik yatak odası.'}, {'id': 396, 'text': 'Victor approached the table and looked down at the lifeless, handsome face lying motionless upon the bier.', 'translation': 'Victor masaya yaklaştı ve tabut tahtası üzerinde hareketsiz yatan cansız, yakışıklı yüze baktı.', 'notes': 'motionless upon the bier: tabut/kerevet üzerinde hareketsiz.'}, {'id': 397, 'text': 'It was Henry Clerval, his dearest and most loyal friend, brutally murdered by demonic hands!', 'translation': "Bu kişi, şeytani eller tarafından hunharca katledilmiş en sevgili ve sadık dostu Henry Clerval'dı!", 'notes': 'demonic hands: şeytani eller.'}, {'id': 398, 'text': "On Henry's neck were the clear, black marks of gigantic fingers, the unmistakable signature of the daemon.", 'translation': "Henry'nin boynunda dev parmakların net, kara izleri vardı; iblisin o inkâr edilemez imzası!", 'notes': 'unmistakable signature: şüphe götürmez imza.'}, {'id': 399, 'text': '"Have my unholy creations no end to their murderous appetite?" Victor shrieked in unbearable agony.', 'translation': '"Benim o lanetli yaratımlarımın cinayet iştahının hiç sonu gelmeyecek mi?" diye katlanılmaz bir acıyla çığlık attı Victor.', 'notes': 'murderous appetite: cinayet iştahı.'}, {'id': 400, 'text': 'Overcome by grief and horror, Victor collapsed onto the cold stone floor into a violent two-month delirium.', 'translation': 'Keder ve dehşetle sarsılan Victor, iki ay sürecek şiddetli bir hezeyan nöbetiyle soğuk taş zemine yığıldı.', 'notes': 'violent delirium: şiddetli sayıklama/hezeyan.'}]}, {'page_no': 21, 'title': 'Acquittal, Guilt, and the Geneva Wedding', 'tr_title': "Beraat, Suçluluk ve Cenevre'de Düğün", 'vocab_focus': [('fever', 'ateş, humma'), ('inquiry', 'soruşturma'), ('alibi', 'olay anında başka yerde olma kanıtı'), ('acquitted', 'beraat etmiş, aklanmış'), ('reassure', 'rahatlatmak, teselli etmek'), ('consenting', 'razı olan, onaylayan'), ('impending', 'yaklaşan, eli kulağında'), ('pistol', 'tabanca')], 'sentences': [{'id': 401, 'text': 'For two long months, Victor hovered between life and death in the gloomy Irish prison chamber.', 'translation': "İrlanda'nın kasvetli hapishane hücresinde Victor iki uzun ay boyunca ölümle yaşam arasında gidip geldi.", 'notes': 'hovered between life and death: ölümle kalım arasında bocaladı.'}, {'id': 402, 'text': 'In his feverish ravings, he constantly accused himself of murdering William, Justine, and Henry.', 'translation': "Ateşli sayıklamalarında William, Justine ve Henry'yi öldürmekle sürekli kendini suçluyordu.", 'notes': 'feverish ravings: ateşli hezeyanlar/sayıklamalar.'}, {'id': 403, 'text': 'Magistrate Kirwin, realizing Victor was a gentleman driven mad by grief, showed him extraordinary kindness.', 'translation': "Victor'ın kederden aklını yitirmiş bir beyefendi olduğunu fark eden Yargıç Kirwin, ona olağanüstü bir nezaket gösterdi.", 'notes': 'extraordinary kindness: olağanüstü nezaket.'}, {'id': 404, 'text': "To Victor's immense joy, his aging father Alphonse arrived in Ireland to nurse his stricken son.", 'translation': "Victor'ın sonsuz mutluluğuna vesile olarak, yaşlı babası Alphonse hasta oğluna bakmak üzere İrlanda'ya geldi.", 'notes': 'stricken son: felakete uğramış/hasta oğul.'}, {'id': 405, 'text': 'A formal legal inquiry proved beyond doubt that Victor was still in the Orkneys when Henry was killed.', 'translation': "Resmi bir adli soruşturma, Henry öldürüldüğünde Victor'ın hâlâ Orkney Adaları'nda olduğunu şüpheye yer bırakmayacak şekilde kanıtladı.", 'notes': 'formal legal inquiry: resmi adli soruşturma.'}, {'id': 406, 'text': "Victor was fully acquitted by the grand jury and released from prison into his father's gentle care.", 'translation': 'Büyük jüri tarafından tamamen beraat ettirilen Victor, hapishaneden çıkarılıp babasının şefkatli ellerine teslim edildi.', 'notes': 'fully acquitted: tamamen aklanmış/beraat etmiş.'}, {'id': 407, 'text': 'Yet Victor felt no joy in freedom, for he considered himself the true murderer of those innocent souls.', 'translation': 'Yine de Victor özgürlükten hiçbir sevinç duymadı; zira kendisini o masum ruhların asıl katili sayıyordu.', 'notes': 'true murderer: gerçek katil.'}, {'id': 408, 'text': '"I am the assassin of William, of Justine, and of Henry!" Victor whispered repeatedly to his bewildered father.', 'translation': '"William\'ın, Justine\'in ve Henry\'nin katili benim!" diye fısıldıyordu Victor şaşkın babasına tekrar tekrar.', 'notes': 'bewildered father: şaşkına dönmüş baba.'}, {'id': 409, 'text': "Alphonse believed these wild confessions were merely lingering symptoms of his son's nervous illness.", 'translation': 'Alphonse bu çılgınca itirafların oğlunun sinir hastalığından arta kalan belirtiler olduğuna inanıyordu.', 'notes': 'lingering symptoms: kalıcı/geçmeyen belirtiler.'}, {'id': 410, 'text': 'Together, father and son traveled slowly through Paris and returned home to their grand estate in Geneva.', 'translation': "Baba oğul Paris üzerinden yavaşça yol alarak Cenevre'deki görkemli malikanelerine döndüler.", 'notes': 'grand estate: büyük köşk/malikane.'}, {'id': 411, 'text': 'Elizabeth welcomed Victor with warm tears and tender devotion, noticing how frail and pale he had become.', 'translation': "Elizabeth, ne kadar zayıf ve solgun düştüğünü fark ettiği Victor'ı sıcak gözyaşları ve şefkatli bir bağlılıkla karşıladı.", 'notes': 'tender devotion: şefkatli bağlılık.'}, {'id': 412, 'text': 'In a private letter, Elizabeth asked Victor if he loved another woman, offering to release him from their betrothal.', 'translation': "Özel bir mektupta Elizabeth, Victor'a başka bir kadını sevip sevmediğini sorarak onu nişanlarından azat etmeyi teklif etti.", 'notes': 'release from betrothal: nişandan azat etmek/ayrılmak.'}, {'id': 413, 'text': '"My beloved Elizabeth, you are the only hope and light remaining in my dark existence," Victor replied.', 'translation': '"Sevgili Elizabeth\'im, benim karanlık varlığımda kalan yegane umut ve ışık sensin," diye yanıtladı Victor.', 'notes': 'dark existence: karanlık varoluş.'}, {'id': 414, 'text': 'Remembering the monster\'s warning—"I shall be with you on your wedding-night"—Victor believed he himself would die.', 'translation': 'Canavarın uyarısını—"Düğün gecende seninle olacağım"—hatırlayan Victor, bizzat kendisinin öleceğine inanıyordu.', 'notes': 'wedding-night warning: düğün gecesi uyarısı.'}, {'id': 415, 'text': 'If he must perish in battle against the daemon, he would at least grant Elizabeth marital happiness first.', 'translation': "İblisle yapacağı savaşta ölecek bile olsa, hiç değilse önce Elizabeth'e evlilik mutluluğunu tattırmak istiyordu.", 'notes': 'marital happiness: evlilik saadeti.'}, {'id': 416, 'text': 'The wedding ceremony was celebrated with quiet elegance in Geneva on a sunny summer morning.', 'translation': "Düğün merasimi güneşli bir yaz sabahında Cenevre'de sessiz bir zarafet içinde kutlandı.", 'notes': 'quiet elegance: sessiz bir zarafet.'}, {'id': 417, 'text': 'Victor wore two loaded pistols concealed beneath his coat, ready to defend himself to the death.', 'translation': 'Victor ceketinin altına gizlenmiş dolu iki tabanca taşıyordu; ölümüne savaşmaya hazırdı.', 'notes': 'loaded pistols: dolu tabancalar.'}, {'id': 418, 'text': 'Alphonse smiled happily, believing his beloved family had finally found peace after endless sorrows.', 'translation': 'Sevgili ailesinin bitmek bilmeyen kederlerden sonra nihayet huzur bulduğuna inanan Alphonse mutlulukla gülümsüyordu.', 'notes': 'endless sorrows: sonsuz kederler.'}, {'id': 419, 'text': 'After the banquet, the newlyweds boarded a scenic barge to cross Lake Como toward an inn at Evian.', 'translation': "Ziyafetin ardından yeni evliler, Evian'daki bir hana doğru Como Gölü'nü geçmek için manzaralı bir tekneye bindiler.", 'notes': 'scenic barge: manzaralı tekne/mavna.'}, {'id': 420, 'text': "As the sun set behind the majestic Alpine peaks, Victor's anxiety mounted into agonizing terror.", 'translation': "Güneş görkemli Alp zirvelerinin ardında batarken, Victor'ın tedirginliği dayanılmaz bir dehşete dönüştü.", 'notes': 'agonizing terror: kahredici dehşet.'}]}, {'page_no': 22, 'title': "The Bride's Death on Lake Como", 'tr_title': "Como Gölü'nde Gelinin Katli", 'vocab_focus': [('inn', 'han, konukevi'), ('restless', 'huzursuz, yerinde duramayan'), ('screaming', 'çığlık atma, feryat'), ('lifeless', 'cansız, ölü'), ('horror', 'dehşet'), ('shattered', 'tuzla buz olmuş, mahvolmuş'), ('mockery', 'alay, alaycılık'), ('apoplexy', 'inme, felç')], 'sentences': [{'id': 421, 'text': 'Darkness fell over the tranquil waters of Lake Como as Victor and Elizabeth reached the inn at Evian.', 'translation': "Victor ile Elizabeth Evian'daki hana ulaştıklarında, Como Gölü'nün dingin sularının üzerine karanlık çöktü.", 'notes': 'tranquil waters: dingin sular.'}, {'id': 422, 'text': 'The wind began to rise, whistling ominously through the ancient pines surrounding the lakeshore.', 'translation': 'Rüzgâr yükselmeye başladı ve göl kıyısını çevreleyen kadim çamların arasından meşum şekilde ıslık çaldı.', 'notes': 'whistling ominously: uğursuzca ıslık çalarak.'}, {'id': 423, 'text': 'Victor paced restlessly along the corridors of the inn, clutching his concealed pistols in trembling hands.', 'translation': 'Victor titreyen elleriyle gizli tabancalarını kavrayarak hanın koridorlarında huzursuzca volta attı.', 'notes': 'paced restlessly: huzursuzca adımladı/volta attı.'}, {'id': 424, 'text': '"Retire to our chamber, my love," Victor whispered gently to Elizabeth; "I must inspect the grounds."', 'translation': '"Odamıza çekil sevgilim," diye fısıldadı Victor Elizabeth\'e nazikçe; "Ben etrafı kolaçan etmeliyim."', 'notes': 'inspect the grounds: etrafı kontrol etmek.'}, {'id': 425, 'text': 'He searched every dark passage and shadowy corner of the building, expecting the monster to leap upon him.', 'translation': 'Canavarın her an üzerine atılmasını bekleyerek binanın her karanlık geçidini ve gölgeli köşesini aradı.', 'notes': 'shadowy corner: gölgeli köşe.'}, {'id': 426, 'text': "Suddenly, a shrill and dreadful scream echoed through the stillness from Elizabeth's bridal chamber!", 'translation': "Ansızın, Elizabeth'in gelin odasından sessizliği yırtan tiz ve dehşet verici bir çığlık yankılandı!", 'notes': 'shrill and dreadful scream: tiz ve korkunç çığlık.'}, {'id': 427, 'text': "In an instant, the horrifying truth struck Victor's soul with the force of a thunderbolt.", 'translation': "Bir anda o korkunç gerçek, bir yıldırımın şiddetiyle Victor'ın ruhuna çarptı.", 'notes': 'force of a thunderbolt: yıldırım şiddeti.'}, {'id': 428, 'text': 'The fiend had never intended to kill Victor on that night; Elizabeth was his true target!', 'translation': "İblis o gece asla Victor'ı öldürmeyi amaçlamamıştı; asıl hedefi Elizabeth'ti!", 'notes': 'true target: asıl hedef.'}, {'id': 429, 'text': 'Victor rushed into the bedroom and saw Elizabeth lying motionless across the bridal bed.', 'translation': "Victor yatak odasına daldı ve Elizabeth'i gelin yatağının üzerinde hareketsiz yatarken gördü.", 'notes': 'bridal bed: gelin yatağı.'}, {'id': 430, 'text': 'Her head hung down, her pale face was twisted in terror, and her gentle neck bore the fatal black marks.', 'translation': 'Başı aşağı sarkmıştı, solgun yüzü dehşetle buruşmuştu ve narin boynunda o ölümcül kara izler duruyordu.', 'notes': 'fatal black marks: ölümcül siyah izler.'}, {'id': 431, 'text': '"Elizabeth! Speak to me, my love, my angel!" Victor wept, falling across her lifeless body in total agony.', 'translation': '"Elizabeth! Konuş benimle sevgilim, meleğim!" diye feryat etti Victor, mutlak bir ızdırapla onun cansız bedenine kapaklanarak.', 'notes': 'total agony: mutlak ızdırap.'}, {'id': 432, 'text': 'Raising his eyes in despair, Victor saw a giant silhouette framed in the open window against the moonlight.', 'translation': 'Umutsuzlukla gözlerini kaldıran Victor, ay ışığına karşı açık pencerenin pervazında devasa bir siluet gördü.', 'notes': 'giant silhouette: devasa silüet.'}, {'id': 433, 'text': "The grinning monster pointed a scornful finger at Elizabeth's corpse, laughing in hideous triumph!", 'translation': "Sırıtan canavar, iğrenç bir zafer sarhoşluğuyla kahkahalar atarak Elizabeth'in cesedine alaycı bir parmak uzattı!", 'notes': 'hideous triumph: iğrenç zafer.'}, {'id': 434, 'text': 'Victor drew his pistol and fired a shot, but the agile daemon leapt into the lake and vanished into the darkness.', 'translation': 'Victor tabancasını çekip ateş etti ama çevik iblis göle atladı ve karanlıkta gözden kayboldu.', 'notes': 'agile daemon: çevik iblis.'}, {'id': 435, 'text': 'The gunshots alarmed the innkeeper and servants, who gathered in horror around the tragic spectacle.', 'translation': 'Silah sesleri hancı ve uşakları ayağa kaldırdı; hepsi bu trajik manzara etrafında dehşetle toplandı.', 'notes': 'tragic spectacle: trajik manzara.'}, {'id': 436, 'text': 'Overwhelmed by grief, Victor was escorted back to Geneva under the constant supervision of anxious friends.', 'translation': "Kederle mahvolan Victor, endişeli dostlarının sürekli gözetimi altında Cenevre'ye geri götürüldü.", 'notes': 'constant supervision: sürekli gözetim.'}, {'id': 437, 'text': 'When Alphonse Frankenstein learned that his beloved adopted daughter was dead, his fragile heart shattered completely.', 'translation': 'Alphonse Frankenstein çok sevdiği evlatlığının öldüğünü öğrenince, o kırılgan kalbi tamamen parçalandı.', 'notes': 'fragile heart: narin/kırılgan kalp.'}, {'id': 438, 'text': "Unable to bear the loss of his entire family, the noble old man suffered an apoplectic stroke and died in Victor's arms.", 'translation': "Bütün ailesinin kaybına dayanamayan o asil ihtiyar felç geçirdi ve Victor'ın kollarında son nefesini verdi.", 'notes': 'apoplectic stroke: inme, felç.'}, {'id': 439, 'text': 'Within a few tragic years, Victor had lost his mother, William, Justine, Henry, Elizabeth, and his father.', 'translation': "Birkaç trajik yıl içinde Victor annesini, William'ı, Justine'i, Henry'yi, Elizabeth'i ve babasını kaybetmişti.", 'notes': 'tragic years: acı dolu yıllar.'}, {'id': 440, 'text': 'Alone in a desolate world, Victor fell into a period of profound madness, locked away in a solitary cell.', 'translation': 'Issız bir dünyada yapayalnız kalan Victor, tek kişilik bir hücreye kilitlenerek derin bir delilik dönemine sürüklendi.', 'notes': 'solitary cell: tek kişilik hücre.'}]}, {'page_no': 23, 'title': 'The Vow of Vengeance and the Arctic Chase', 'tr_title': 'İntikam Yemini ve Kutup Takibi', 'vocab_focus': [('cemetery', 'mezarlık'), ('tomb', 'mezar, kabir'), ('fiend', 'iblis, canavar'), ('pursuit', 'takip, kovalama'), ('wilderness', 'yaban hayatı, ıssızlık'), ('sledge', 'kızak'), ('taunting', 'alay eden, kışkırtan'), ('tundra', 'tundra, donmuş bozkır')], 'sentences': [{'id': 441, 'text': "When Victor's sanity slowly returned, his overwhelming sorrow transformed into cold, relentless rage.", 'translation': "Victor'ın aklı yavaş yavaş yerine geldiğinde, dayanılmaz acısı soğuk ve amansız bir öfkeye dönüştü.", 'notes': 'relentless rage: amansız öfke.'}, {'id': 442, 'text': 'He visited the town magistrate in Geneva, demanding that soldiers hunt down the superhuman murderer.', 'translation': "Cenevre'deki kasaba yargıcını ziyaret etti ve askerlerin bu insanüstü katili avlamasını talep etti.", 'notes': 'superhuman murderer: insanüstü katil.'}, {'id': 443, 'text': "The magistrate listened with polite disbelief, regarding Victor's tale as the raving hallucination of a broken mind.", 'translation': "Yargıç kibar bir inançsızlıkla dinledi; Victor'ın anlattıklarını yıkılmış bir zihnin hezeyanlı halüsinasyonları olarak gördü.", 'notes': 'polite disbelief: kibar bir inançsızlık.'}, {'id': 444, 'text': 'Realizing that human law could never bring justice, Victor resolved to execute vengeance with his own hands.', 'translation': 'İnsan yasalarının asla adalet getiremeyeceğini anlayan Victor, intikamı kendi elleriyle almaya karar verdi.', 'notes': 'execute vengeance: intikam almak.'}, {'id': 445, 'text': 'On a dark, moonlit night, Victor visited the cemetery where William, Elizabeth, and his father were buried.', 'translation': 'Karanlık, mehtaplı bir gecede Victor; William, Elizabeth ve babasının gömülü olduğu mezarlığı ziyaret etti.', 'notes': 'visited the cemetery: mezarlığı ziyaret etti.'}, {'id': 446, 'text': 'Kneeling beside their marble tombs, he touched the cold stone and swore an eternal, sacred oath.', 'translation': 'Mermer kabirlerinin yanında diz çökerek soğuk taşa dokundu ve ebedi, kutsal bir yemin etti.', 'notes': 'sacred oath: kutsal ant/yemin.'}, {'id': 447, 'text': '"I swear by the spirits of the dead to devote my remaining life to destroying the daemon I created!"', 'translation': '"Ölülerin ruhları üzerine ant içerim ki kalan hayatımı yarattığım o iblisi yok etmeye adayacağım!"', 'notes': 'spirits of the dead: ölülerin ruhları.'}, {'id': 448, 'text': 'As his words faded into the nocturnal silence, a loud, demonic laugh echoed among the stone monuments.', 'translation': 'Sözleri gecenin sessizliğinde kaybolurken, taş anıtların arasında gür, şeytani bir kahkaha yankılandı.', 'notes': 'demonic laugh: şeytani kahkaha.'}, {'id': 449, 'text': '"I am satisfied that you have resolved to live, creator," a mocking voice whispered from behind the cypress trees.', 'translation': '"Yaşamaya karar vermiş olmandan pek memnun kaldım, yaratıcım," diye fısıldadı servi ağaçlarının ardından alaycı bir ses.', 'notes': 'mocking voice: alaycı ses.'}, {'id': 450, 'text': 'The chase began that very night, spanning thousands of miles across rugged continents and frozen wastes.', 'translation': 'O amansız kovalamaca tam o gece başladı; sarp kıtalar ve donmuş ıssızlıklar boyunca binlerce mil uzandı.', 'notes': 'frozen wastes: donmuş ıssızlıklar.'}, {'id': 451, 'text': 'Victor pursued his enemy through the Mediterranean, across the snowy plains of Tartary, and deep into Russia.', 'translation': "Victor düşmanını Akdeniz boyunca, Tatarya'nın karlı ovalarından geçirerek Rusya'nın derinliklerine kadar kovaladı.", 'notes': 'snowy plains: karlı ovalar.'}, {'id': 452, 'text': 'The monster deliberately left taunting inscriptions on trees and rocks to ensure Victor never lost the trail.', 'translation': "Canavar, Victor'ın izi asla kaybetmemesini sağlamak için ağaçlara ve kayalara kasten alaycı yazılar kazıyordu.", 'notes': 'taunting inscriptions: alaycı yazıtlar/notlar.'}, {'id': 453, 'text': '"Prepare your furs and weapons, Victor, for the bitter cold of the North shall be our eternal battleground!"', 'translation': '"Kürklerini ve silahlarını hazırla Victor, zira Kuzeyin dondurucu soğuğu bizim ebedi savaş meydanımız olacak!"', 'notes': 'eternal battleground: ebedi savaş meydanı.'}, {'id': 454, 'text': 'As they advanced further north, the bitter winds froze the landscape into an unbroken desert of ice.', 'translation': 'Kuzeyin daha da içlerine ilerledikçe, dondurucu rüzgârlar coğrafyayı kesintisiz bir buz çölüne çevirdi.', 'notes': 'desert of ice: buz çölü.'}, {'id': 455, 'text': 'Victor purchased a sturdy sledge and a pack of fierce northern dogs to traverse the barren tundra.', 'translation': 'Victor çorak tundrayı aşmak için sağlam bir kızak ve bir sürü yırtıcı kuzey köpeği satın aldı.', 'notes': 'sturdy sledge: sağlam kızak.'}, {'id': 456, 'text': "The monster traveled likewise upon a sledge, staying just a few miles ahead, mocking Victor's endurance.", 'translation': "Canavar da benzer şekilde bir kızak üzerinde seyahat ediyor, sadece birkaç mil önde kalarak Victor'ın dayanıklılığıyla alay ediyordu.", 'notes': 'mocking endurance: dayanıklılığıyla alay eden.'}, {'id': 457, 'text': 'Food grew scarce, the temperatures plunged far below zero, and several faithful dogs died of exhaustion.', 'translation': 'Yiyecek kıtlaştı, hava sıcaklığı sıfırın fersah fersah altına indi ve birkaç sadık köpek bitkinlikten can verdi.', 'notes': 'plunged below zero: sıfırın altına indi.'}, {'id': 458, 'text': "Yet Victor's burning thirst for revenge kept his frail, shivering body moving forward through the blizzards.", 'translation': "Fakat Victor'ın içindeki o yakan intikam susuzluğu, bitkin ve titreyen bedenini tipilerin arasından ileriye doğru sürükledi.", 'notes': 'thirst for revenge: intikam susuzluğu.'}, {'id': 459, 'text': "Finally, across a vast sheet of arctic ice, Victor spotted the daemon's sledge less than a mile away!", 'translation': 'Nihayet uçsuz bucaksız bir kutup buzulu tabakasının üzerinde Victor, iblisin kızağını bir milden daha yakın bir mesafede fark etti!', 'notes': 'arctic ice: kutup buzu.'}, {'id': 460, 'text': 'Victor raised his rifle with trembling hands, his heart racing with fierce anticipation of the final confrontation.', 'translation': 'Victor titreyen elleriyle tüfeğini kaldırdı; nihai yüzleşmenin ateşli beklentisiyle kalbi deli gibi çarpıyordu.', 'notes': 'final confrontation: son/nihai yüzleşme.'}]}, {'page_no': 24, 'title': "The Ice Breaks and Victor's Final Breath", 'tr_title': "Kırılan Buzlar ve Victor'ın Son Nefesi", 'vocab_focus': [('fracture', 'çatlak, kırık'), ('drifting', 'sürüklenme'), ('mariners', 'denizciler'), ('emaciated', 'bir deri bir kemik kalmış'), ('ambition', 'aşırı hırs, ihtiras'), ('vanity', 'kibir, nafile gurur'), ('reproach', 'kınamak, sitem etmek'), ('expire', 'son nefesini vermek, ölmek')], 'sentences': [{'id': 461, 'text': 'Just as Victor closed the distance between their sledges, a deafening crack shook the frozen sea.', 'translation': 'Tam Victor kızakları arasındaki mesafeyi kapatmışken, sağır edici bir çatlama sesi donmuş denizi sarstı.', 'notes': 'deafening crack: sağır edici çatlama.'}, {'id': 462, 'text': "A tremendous fracture tore through the ice sheet, separating Victor's sledge from his fleeing quarry.", 'translation': "Muazzam bir kırık buz tabakasını yarıp geçti ve Victor'ın kızağını kaçan avından ayırdı.", 'notes': 'fleeing quarry: kaçan av.'}, {'id': 463, 'text': 'Within minutes, an expanding channel of black, freezing ocean water surged between the two floating ice floes.', 'translation': 'Birkaç dakika içinde iki yüzen buz kütlesi arasında genişleyen kara, dondurucu okyanus suyu kabardı.', 'notes': 'floating ice floes: yüzen buz kütleleri.'}, {'id': 464, 'text': 'The daemon rode away toward the north on his ice island, while Victor drifted helplessly southward.', 'translation': 'İblis kendi buz adasının üzerinde kuzeye doğru uzaklaşırken, Victor çaresizce güneye sürüklendi.', 'notes': 'drifted Southward: güneye sürüklendi.'}, {'id': 465, 'text': "Several of Victor's remaining dogs died on the ice raft, and he prepared to perish from exposure and starvation.", 'translation': "Victor'ın kalan köpeklerinden birkaçı buz salında öldü ve kendisi de donarak ve açlıktan ölmeye hazırlandı.", 'notes': 'exposure and starvation: soğuk ve açlık.'}, {'id': 466, 'text': "It was at that desperate moment that Captain Walton's icebound ship appeared through the thick arctic fog.", 'translation': "Kaptan Walton'ın buzlara sıkışmış gemisinin yoğun kutup sisinin içinden belirmesi tam da bu umutsuz anda oldu.", 'notes': 'icebound ship: buzlar arasında sıkışmış gemi.'}, {'id': 467, 'text': 'The compassionate sailors hoisted Victor aboard, wrapping his emaciated and frostbitten limbs in warm blankets.', 'translation': "Merhametli denizciler Victor'ı gemiye çektiler ve bir deri bir kemik kalmış, donmuş uzuvlarını sıcak battaniyelere sardılar.", 'notes': 'frostbitten limbs: donmuş uzuvlar.'}, {'id': 468, 'text': 'Over the following days, Victor recounted his tragic history to Walton, who recorded every word in his journal.', 'translation': "Takip eden günlerde Victor o trajik geçmişini Walton'a anlattı ve Walton her kelimeyi günlüğüne kaydetti.", 'notes': 'recounted his history: geçmişini anlattı.'}, {'id': 469, 'text': '"Learn from my grievous misfortunes, Captain Walton," Victor warned with feeble but passionate intensity.', 'translation': '"Benim feci talihsizliklerimden ibret al, Kaptan Walton," diye uyardı Victor zayıf ama tutkulu bir şiddetle.', 'notes': 'grievous misfortunes: feci talihsizlikler.'}, {'id': 470, 'text': '"Seek peace in tranquil domestic life and avoid that reckless ambition which seeks to transcend human boundaries."', 'translation': '"Huzuru dingin bir aile hayatında ara ve insan sınırlarını aşmaya çalışan o pervasız hırstan uzak dur."', 'notes': 'reckless ambition: pervasız hırs.'}, {'id': 471, 'text': "Meanwhile, the crew of Walton's ship threatened mutiny, demanding that the captain return to England once freed.", 'translation': "Bu sırada Walton'ın gemisinin mürettebatı, buzlar açıldığında kaptanın İngiltere'ye dönmesini talep ederek isyan çıkarmakla tehdit etti.", 'notes': 'threatened mutiny: isyanla tehdit etti.'}, {'id': 472, 'text': 'Gathering his remaining strength, Victor addressed the frightened sailors with magnificent eloquence from his bed.', 'translation': 'Kalan son gücünü toplayan Victor, yatağından korkmuş denizcilere muazzam bir belagatla hitap etti.', 'notes': 'magnificent eloquence: muazzam belagat/etkileyici konuşma.'}, {'id': 473, 'text': '"Do not return home as cowards who feared the glorious ice; be brave and conquer the elements like men!"', 'translation': '"Görkemli buzlardan korkan korkaklar olarak eve dönmeyin; cesur olun ve doğayı mertçe fethedin!"', 'notes': 'conquer the elements: doğa unsurlarını fethetmek.'}, {'id': 474, 'text': 'Yet Walton knew that his duty was to preserve the lives of his crew rather than pursue useless glory.', 'translation': 'Yine de Walton, görevinin beyhude bir zafer peşinde koşmaktansa mürettebatının hayatını korumak olduğunu biliyordu.', 'notes': 'useless glory: beyhude zafer/şöhret.'}, {'id': 475, 'text': "Victor understood Walton's wise decision and smiled faintly, his vital energy draining rapidly away.", 'translation': "Victor Walton'ın bu bilgece kararını anladı ve yaşam enerjisi hızla tükenirken belli belirsiz gülümsedi.", 'notes': 'vital energy: yaşam enerjisi.'}, {'id': 476, 'text': '"My mission remains unfulfilled," Victor murmured weakly, clutching Walton\'s hand in the dim cabin light.', 'translation': '"Görevim yarım kaldı," diye mırıldandı Victor zayıfça, loş kamara ışığında Walton\'ın elini tutarak.', 'notes': 'remains unfulfilled: yarım kalmış, tamamlanmamış.'}, {'id': 477, 'text': '"Yet I do not reproach myself for my decisions; another may yet succeed where I have fallen."', 'translation': '"Yine de aldığım kararlar için kendimi kınamıyorum; benim düştüğüm yerde bir başkası henüz başarabilir."', 'notes': 'reproach myself: kendimi kınamak.'}, {'id': 478, 'text': "He closed his weary eyes, whispering Elizabeth's beloved name with his final fading breath.", 'translation': "Tükenmiş gözlerini kapadı ve sönen son nefesiyle sevgili Elizabeth'inin adını fısıldadı.", 'notes': 'fading breath: tükenen son nefes.'}, {'id': 479, 'text': 'Captain Walton wept bitterly at the bedside of his remarkable and tragic friend.', 'translation': 'Kaptan Walton o olağanüstü ve trajik dostunun yatağı başında acı acı gözyaşı döktü.', 'notes': 'wept bitterly: acı acı ağladı.'}, {'id': 480, 'text': 'Victor Frankenstein, the ambitious creator who sought the secrets of life, was dead at last.', 'translation': 'Hayatın sırlarını arayan o hırslı yaratıcı, Victor Frankenstein nihayet ölmüştü.', 'notes': 'dead at last: nihayet ölmüş.'}]}, {'page_no': 25, 'title': "The Creature's Lament and the Funeral Pyre", 'tr_title': 'Yaratığın Ağıtı ve Buzlardaki Cenaze Ateşi', 'vocab_focus': [('lamentation', 'ağıt, feryat'), ('repentance', 'pişmanlık, tövbe'), ('unfathomable', 'akıl almaz, dipsiz'), ('wretchedness', 'sefalet, perişanlık'), ('funeral pyre', 'cenaze ateşi'), ('ashes', 'küller'), ('extinguish', 'söndürmek, yok etmek'), ('darkness', 'karanlık')], 'sentences': [{'id': 481, 'text': "Later that night, while Walton sat writing beside Victor's bier, a mournful wail echoed through the cabin.", 'translation': "O gecenin ilerleyen saatlerinde Walton Victor'ın naşının başında oturup yazarken, kamarada hüzünlü bir feryat yankılandı.", 'notes': 'mournful wail: kederli feryat/inilti.'}, {'id': 482, 'text': 'Walton entered the room and discovered a monstrous figure towering over the lifeless corpse of Victor.', 'translation': "Walton odaya girdi ve Victor'ın cansız cesedinin üzerine eğilmiş heybetli, canavarımsı bir siluet keşfetti.", 'notes': 'monstrous figure: canavarımsı figür.'}, {'id': 483, 'text': 'The gigantic creature was weeping bitter tears, his repulsive face contorted with unfathomable grief.', 'translation': 'Dev yaratık acı gözyaşları döküyordu; itici yüzü dipsiz bir kederle buruşmuştu.', 'notes': 'unfathomable grief: dipsiz, akıl almaz keder.'}, {'id': 484, 'text': '"Oh, Frankenstein! Generous and noble creator, what does it avail you that I ask for pardon?"', 'translation': '"Ah Frankenstein! Cömert ve asil yaratıcım, şimdi senden af dilememin sana ne faydası var ki?"', 'notes': 'ask for pardon: af dilemek.'}, {'id': 485, 'text': 'Walton stepped forward, torn between instinctive horror and an unexpected surge of profound pity.', 'translation': 'İçgüdüsel bir dehşet ile beklenmedik bir derin acıma duygusu arasında bocalayan Walton ileri bir adım attı.', 'notes': 'profound pity: derin merhamet/acıma.'}, {'id': 486, 'text': '"Your repentance comes far too late, fiend," Walton declared sternly; "you murdered this great man!"', 'translation': '"Pişmanlığın çok geç geldi iblis," diye sertçe çıkıştı Walton; "Sen bu harika adamı öldürdün!"', 'notes': 'repentance: pişmanlık, tövbe.'}, {'id': 487, 'text': '"Do you think that I was insensible to the agony of my crimes?" the daemon asked with broken sobs.', 'translation': '"İşlediğim suçların azabına karşı hissiz olduğumu mu sanıyorsun?" diye sordu iblis boğuk hıçkırıklarla.', 'notes': 'broken sobs: boğuk hıçkırıklar.'}, {'id': 488, 'text': '"Every blow I struck against Victor pierced my own wretched heart with equal, agonizing torment."', 'translation': '"Victor\'a indirdiğim her darbe, benim kendi zavallı kalbimi de aynı kahredici eziyetle delip geçti."', 'notes': 'agonizing torment: kahredici eziyet.'}, {'id': 489, 'text': '"My heart was fashioned to love, to cherish goodness, and to admire the beauty of human virtue."', 'translation': '"Benim kalbim sevmeye, iyiliği el üstünde tutmaya ve insan erdeminin güzelliğine hayran olmaya göre yaratılmıştı."', 'notes': 'human virtue: insan erdemi.'}, {'id': 490, 'text': '"Yet every door was slammed against me; humanity drove me into bloodshed through cruelty and cold rejection."', 'translation': '"Oysa her kapı yüzüme çarpıldı; insanlık zalimliği ve soğuk dışlamasıyla beni kan dökmeye itti."', 'notes': 'cold rejection: soğuk dışlama/reddediliş.'}, {'id': 491, 'text': '"I became a monster not from choice, but because total solitude tore my gentle soul to pieces."', 'translation': '"Kendi tercihimle değil, zifiri yalnızlık nazik ruhumu paramparça ettiği için bir canavara dönüştüm."', 'notes': 'total solitude: mutlak yalnızlık.'}, {'id': 492, 'text': '"Now my creator is dead, and the tragic drama of our interconnected lives has reached its final act."', 'translation': '"Artık yaratıcım öldü ve birbirine bağlı hayatlarımızın o trajik dramı son perdesine ulaştı."', 'notes': 'final act: son perde/bölüm.'}, {'id': 493, 'text': '"Fear not that I will ever harm another human being," the creature declared with solemn dignity.', 'translation': '"Bir başka insana asla zarar vereceğimden korkma," diye ilan etti yaratık vakur bir vakarla.', 'notes': 'solemn dignity: ağırbaşlı vakar.'}, {'id': 494, 'text': '"I shall quit your vessel immediately and journey across the northernmost ice fields to the farthest pole."', 'translation': '"Gemini derhal terk edecek ve en kuzeydeki buz tarlalarını aşarak en uzak kutba doğru yol alacağım."', 'notes': 'quit vessel: gemiden ayrılmak.'}, {'id': 495, 'text': '"There I will collect driftwood, build a gigantic funeral pyre, and burn this miserable frame to ashes."', 'translation': '"Orada karaya vurmuş odunları toplayacak, devasa bir cenaze ateşi yakacak ve bu zavallı iskeletimi küle çevireceğim."', 'notes': 'funeral pyre: cenaze ateşi.'}, {'id': 496, 'text': '"My body will be consumed by the flames, and the northern winds will scatter my dust across the sea."', 'translation': '"Bedenim alevler içinde kül olacak ve kuzey rüzgârları tozumu denizlerin üzerine savuracak."', 'notes': 'consumed by flames: alevlerce yutulmuş/tüketilmiş.'}, {'id': 497, 'text': '"Thus the only creature of my kind shall vanish, and no future scientist shall repeat my creator\'s fatal mistake."', 'translation': '"Böylece türümün tek örneği yok olup gidecek ve gelecekte hiçbir bilim insanı yaratıcımın o ölümcül hatasını tekrarlamayacak."', 'notes': 'fatal mistake: ölümcül hata.'}, {'id': 498, 'text': '"Farewell, Walton! Farewell, Frankenstein, the only being who ever gave me life!"', 'translation': '"Elveda Walton! Elveda Frankenstein, bana bu hayatı veren yegane varlık!"', 'notes': 'farewell: elveda.'}, {'id': 499, 'text': 'With a mighty leap, the daemon sprang through the cabin window onto the floating ice raft beside the ship.', 'translation': 'Güçlü bir sıçrayışla iblis kamara penceresinden geminin yanındaki yüzen buz salının üzerine atladı.', 'notes': 'mighty leap: kudretli sıçrayış.'}, {'id': 500, 'text': 'Borne away by the surging arctic currents, he was soon lost in darkness and distance forever.', 'translation': 'Kabaran kutup akıntılarına kapılarak, kısa süre sonra sonsuza dek karanlıkta ve uzaklarda kaybolup gitti.', 'notes': 'lost in darkness: karanlıkta kaybolmuş.'}]}]
